(35, '7866610450480', 5, 'https://www.greats.com/products/the-reign-ecru-mens', 'Shoes', 'Sneakers', 'Greats', 'The Reign - Ecru', 'Meet the new classic. The Reign reimagines the low-profile sneaker with a modern point of view. Handcrafted in Portugal from Candiani Italian denim and Italian suede, it pairs refined materials with responsible innovation. The denim upper combines Regenagri® Blue Seed Cotton with recycled cotton from old jeans, creating a premium fabric that’s as considered as it is wearable. Finished with waxed cotton laces and a natural rubber sole, Reign delivers effortless style with a reduced environmental impact. Minimal by design. Timeless by nature.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/REIT03SG-280_1.jpg?v=1769550929', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Denim', 'Caoutchouc', 'Lacets', 'homme', 'Sneaker confortable et durable', 1, 80.0526, 2, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain, actif, tendance\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"passionné par la mode\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements sportifs\",\n      \"rendez-vous amoureux\"\n   ]\n}', 0.369892, -0.596804, 80.0452),
(36, '7866064666672', 5, 'https://www.greats.com/products/the-royale-knit-2-0-navy-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale Knit 2.0 - Navy', 'The Royale Knit 2.0 is GREATS\' lightweight classic, crafted with vegan materials and recycled plastic. Breathable, flexible, and easy to clean, it’s built for everyday adventure. Its featherweight knit upper keeps the iconic silhouette while minimizing bulk, and its durable construction wears as effortlessly as it moves—beat it up, wear it in, then simply rinse with soap and water.', 179.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYK03SG-9UU_2_68980493-6b85-4ec1-af7c-ccdf74612fa3.jpg?v=1769549449', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Coton', 'Caoutchouc', 'Lacets', 'femme', 'Sneaker légère et respirante', 1, 81.1053, 2, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confident\": true,\n      \"independent\": true,\n      \"éclectique\": true,\n      \"appreciate la qualité\": true,\n      \"conscient de l\'impact environnemental\": true\n   },\n   \"occasion_port\": {\n      \"jour de travail\": true,\n      \"sorties nocturnes\": true,\n      \"week-end en ville\": true,\n      \"événements sportifs\": true\n   }\n}', 0.0936023, -0.389594, 81.0924),
