(38, '7866064502832', 5, 'https://www.greats.com/products/the-brooklyn-white-baby-blue-womens', 'Shoes', 'Sneakers', 'Greats', 'The Brooklyn - White Baby Blue', 'Get to know Brooklyn. Coffee in hand, city streets underfoot, evening plans ahead. A low-profile silhouette crafted in soft leather and tonal suede, with a subtle wedge for all-day comfort. Brooklyn blends everyday polish with a hint of retro heritage—the sneaker you’ll reach for again and again. A touch of nostalgia, always effortless, it’s the everyday sneaker that never goes out of style.', 189.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/BROOKLYN_BROK02SG-WBB_1_52f3382c-52ee-4ec6-b421-231b067c83ac.jpg?v=1769548625', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Sneaker confortable et durable', 1, 80.5789, 2, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain, tendance, créatif\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independant\",\n      \"passionné par la mode\",\n      \"appreciate la qualité et l\'originalité\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements sociaux\",\n      \"rendez-vous amoureux\",\n      \"jour de travail\"\n   ]\n}', 0.460434, -0.413131, 80.5734),
