(40, '7777073987632', 5, 'https://www.greats.com/products/the-royale-2-0-blanco-womens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Blanco', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. A n evolved fit that feels impossibly comfortable right out of the box; gold foil branding details; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life in white sneakers for women .', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/RYLL02SG-84D-01_56d4df84-8cf5-46a7-ab12-c6e0a790ac14.jpg?v=1762374368', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'femme', 'Sneaker confortable et durable', 1, 80.0526, 2, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"activite\": \"urbain\",\n      \"loisirs\": [\"musique\", \"cinéma\", \"restauration\"],\n      \"mode_de_vie\": \"urbain dynamique\"\n   },\n   \"traits_personnalite\": {\n      \"ambitieux\": true,\n      \"independant\": true,\n      \"conformiste\": false,\n      \"éclectique\": true\n   },\n   \"occasion_port\": {\n      \"soirée\": true,\n      \"rendez-vous\": true,\n      \"sortie avec amis\": true,\n      \"événement de style\": true\n   }\n}', 0.460434, -0.413131, 80.0452);
