(41, '7730160042032', 5, 'https://www.greats.com/products/the-ravine-olive-mens', 'Shoes', 'Sneakers', 'Greats', 'The Ravine - Olive', 'Step into versatility with The Ravine, a modern light hiker built for city streets and outdoor adventures alike. Durable, weather-resistant, and cushioned for comfort, this sneaker–hiker hybrid is designed to move with you. The Ravine is ready when the sidewalk ends—your go-to for exploration without compromise.', 225.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/RAVL01SG-6F0_1.jpg?v=1756929788', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Synthétique', 'Plateforme', 'Lacets', 'homme', 'Chaussure versatile pour les aventures urbaines et extérieures', 1, 78.6842, 4, '{\n  \"nom_persona\": \"Léa\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"activité\": \"urbaine\",\n      \"loisirs\": [\"musique\", \"cinéma\", \"voyages\"],\n      \"mode_de_vie\": \"équilibré\"\n   },\n   \"traits_personnalite\": {\n      \"confiance\": \"élevée\",\n      \"ouverture\": \"ouverte\",\n      \"éclectisme\": \"fort\"\n   },\n   \"occasion_port\": {\n      \"occasion\": \"journée de travail\",\n      \"activité\": \"réunion de travail\",\n      \"lieu\": \"bureau\"\n   }\n}', -0.0444242, -0.297083, 78.6825),
(42, '7730160009264', 5, 'https://www.greats.com/products/the-ravine-blanco-mens', 'Shoes', 'Sneakers', 'Greats', 'The Ravine - Blanco', 'Step into versatility with The Ravine, a modern light hiker built for city streets and outdoor adventures alike. Durable, weather-resistant, and cushioned for comfort, this sneaker–hiker hybrid is designed to move with you. The Ravine is ready when the sidewalk ends—your go-to for exploration without compromise.', 168.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/RAVL01SG-84D_1.jpg?v=1756929789', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Synthétique', 'Plateforme', 'Lacets', 'homme', 'Chaussure versatile pour les aventures urbaines et extérieures', 1, 81.6321, 4, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain actif\",\n   \"traits_personnalite\": {\n      \"confident\": 8,\n      \"independant\": 7,\n      \"éclectique\": 9,\n      \"passionné\": 8,\n      \"authentique\": 9\n   },\n   \"occasion_port\": {\n      \"jour de travail\": 30,\n      \"sortie en ville\": 40,\n      \"événement social\": 20,\n      \"loisirs actifs\": 10\n   }\n}', -0.0444242, -0.297083, 81.6378),
(43, '7730160107568', 5, 'https://www.greats.com/products/the-ravine-matte-black-mens', 'Shoes', 'Sneakers', 'Greats', 'The Ravine - Matte Black', 'Step into versatility with The Ravine, a modern light hiker built for city streets and outdoor adventures alike. Durable, weather-resistant, and cushioned for comfort, this sneaker–hiker hybrid is designed to move with you. The Ravine is ready when the sidewalk ends—your go-to for exploration without compromise.', 225.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/RAVL01SG-002_1.jpg?v=1756929769', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Synthétique', 'Plateforme', 'Lacets', 'homme', 'Chaussure versatile pour les aventures urbaines et extérieures', 1, 78.6842, 4, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain, actif, tendance\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"passionné par la mode\",\n      \"appreciate la qualité et la durabilité\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements sociaux\",\n      \"rendez-vous amoureux\",\n      \"jour de travail\"\n   ]\n}', -0.0444242, -0.297083, 78.6825),
(44, '7761177083952', 5, 'https://www.greats.com/products/the-royale-2-0-matte-black-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Matte Black', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. An evolved fit that feels impossibly comfortable right out of the box; gold foil branding details; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life.', 149.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYL01SG-002_1.jpg?v=1760106006', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker iconique avec un style incontournable', 1, 82.6321, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"ambitieux\",\n      \"independent\",\n      \"décontracté\"\n   ],\n   \"occasion_port\": \"sortie nocturne\",\n   \"intérêts\": [\n      \"musique\",\n      \"cinéma\",\n      \"mode\"\n   ],\n   \"niveau_revenu\": \"moyen-élevé\",\n   \"connaissance_mode\": \"moyenne\",\n   \"influenceurs\": [\n      \"influencers de mode urbain\"\n   ]\n}', 0.515126, 0.400522, 82.6141),
(45, '7730159910960', 5, 'https://www.greats.com/products/the-royale-2-0-crazy-horse-brown-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Crazy Horse Brown', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. An evolved fit that feels impossibly comfortable right out of the box; embossed branding detail; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYL01SG-B57_1_49eed965-ba0e-466d-b25f-42acf3816ba4.jpg?v=1756994684', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker iconique avec un style incontournable', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"tendre pour la qualité\"\n   ],\n   \"occasion_port\": \"soirée en ville, sortie avec des amis\"\n}', 0.515126, 0.400522, 80.0452),
(46, '7233446051888', 5, 'https://www.greats.com/products/the-paros-penny-loafer-sand-mens', 'Shoes', 'Sneakers', 'Greats', 'The Paros Penny Loafer - Sand', 'Introducing Paros, the perfect companion for your laid-back summer weekends. This revamped rendition of the beloved GREATS loafer silhouette is designed to embrace relaxation and vacation vibes. Crafted with luxuriously soft suedes, breathable leather linings, and a sporty sole known for its unparalleled comfort, Paros effortlessly combines timeless style with seasonal flair. It’s the epitome of effortless elegance, offering lasting appeal and a touch of refinement—exactly what summer is all about, isn’t it?', 189.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/PARO01SG-59N-01.jpg?v=1757015614', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'homme', 'Loafer parfait pour les week-ends de vacances', 1, 80.5789, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-45\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"élégant\",\n      \"prévisible\"\n   ],\n   \"occasion_port\": [\n      \"rendez-vous\",\n      \"sorties nocturnes\",\n      \"réunions professionnelles\",\n      \"voyages\"\n   ]\n}', 0.303358, 0.110112, 80.5734),
(47, '7730160173104', 5, 'https://www.greats.com/products/the-manhattan-blanco-mens', 'Shoes', 'Sneakers', 'Greats', 'The Manhattan City Runner - Blanco', 'Meet the Manhattan City Runner—a sneaker built for the rhythm of city life. From subway sprints to weekend walks, it’s lightweight, cushioned, and crafted to keep pace with every step. In the city that never slows down, 10k steps never looked so good.', 225.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/MANL01SG84D-1.jpg?v=1756926009', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Synthétique', 'Gomme', 'Lacets', 'homme', 'Sneaker conçu pour la vie urbaine', 1, 78.6842, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": {\n      \"min\": 25,\n      \"max\": 45\n   },\n   \"style_vie\": {\n      \"ville\": \"New York\",\n      \"activite\": \"course à pied\",\n      \"loisirs\": \"musique, cinéma, restaurants\"\n   },\n   \"traits_personnalite\": {\n      \"ambitieux\": true,\n      \"independant\": true,\n      \"dynamique\": true,\n      \"écologique\": true\n   },\n   \"occasion_port\": {\n      \"occasion\": \"tous les jours\",\n      \"activite\": \"course à pied, travail, sorties\"\n   }\n}', 0.136972, 0.0659138, 78.6825),
(48, '7730159976496', 5, 'https://www.greats.com/products/the-royale-2-0-mineral-black-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Mineral Black', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. An evolved fit that feels impossibly comfortable right out of the box; embossed branding detail; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life.', 149.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYL01SG-014_4_d9148141-ba28-4944-bbbe-1fbabcfd844c.jpg?v=1756994990', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker iconique avec un style incontournable', 1, 82.6321, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"ambitieux\": 0.8,\n      \"independant\": 0.7,\n      \"décontracté\": 0.6,\n      \"passionné\": 0.9\n   },\n   \"occasion_port\": {\n      \"jour de travail\": 0.4,\n      \"sortie avec des amis\": 0.3,\n      \"rendez-vous amoureux\": 0.2,\n      \"événement social\": 0.1\n   }\n}', 0.515126, 0.400522, 82.6141),
(49, '7730159648816', 5, 'https://www.greats.com/products/the-royale-slip-on-2-0-mineral-navy-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale Slip On 2.0 - Mineral Navy', 'A new spin on the shoe that started it all. The effortless cool look of the Royale 2.0, in an effortless slip-on fit. Already impossibly comfortable right out of the box, we replaced the shoelaces with a flexible elasticated panel to help you get out the door (or through airport security) faster. Our buttery smooth full grained leather and suede upper gives it a sleek new look that will carry you from weekend to workweek.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYS01SG-414_2_24c44ca7-92cd-4bcc-b98f-1edd107b30ff.jpg?v=1756995013', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Sneaker slip-on avec un style incontournable', 1, 80.0526, 3, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"décontracté\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"rendez-vous\",\n      \"journées de travail\"\n   ]\n}', -0.296226, 0.575709, 80.0452),
(50, '7730159878192', 5, 'https://www.greats.com/products/the-royale-slip-on-2-0-mineral-taupe-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale Slip On 2.0 - Mineral Taupe', 'A new spin on the shoe that started it all. The effortless cool look of the Royale 2.0, in an effortless slip-on fit. Already impossibly comfortable right out of the box, we replaced the shoelaces with a flexible elasticated panel to help you get out the door (or through airport security) faster. Our buttery smooth full grained leather and suede upper gives it a sleek new look that will carry you from weekend to workweek.', 199.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYS01SG-252_1_6fa462d8-7597-4643-b327-50d8115eb6e0.jpg?v=1756995012', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Sneaker slip-on avec un style incontournable', 1, 80.0526, 3, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"independent\",\n      \"tendance\",\n      \"confiant\",\n      \"prévisible\"\n   ],\n   \"occasion_port\": [\n      \"sortie avec des amis\",\n      \"rendez-vous galant\",\n      \"week-end en ville\",\n      \"réunion professionnelle\"\n   ]\n}', -0.296226, 0.575709, 80.0452),
(51, '7667085803568', 5, 'https://www.greats.com/products/the-corsa-driver-tan-mens', 'Shoes', 'Sneakers', 'Greats', 'The Corsa Driver - Tan', 'Introducing the Corsa Driver, a year-round classic that feels like a slipper and looks like a million bucks. Inspired by the original \'driving\' shoe - think Monza in the 1960s- the Corsa blends the comfort of a moccasin with the traction and durability to withstand daily wear. This hand-sewn style made of buttery-soft suede and full-grained leather has everything to become a wardrobe staple.', 189.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/CORD01SG-269_1.jpg?v=1757010227', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'homme', 'Chaussure de course avec un style incontournable', 1, 80.5789, 1, '{\n  \"nom_persona\": \"Léo\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain actif\",\n   \"traits_personnalite\": {\n      \"motivé\": true,\n      \"ambitieux\": true,\n      \"independent\": true,\n      \"passionné\": true\n   },\n   \"occasion_port\": {\n      \"travail\": \"entrepreneur, professionnel actif\",\n      \"loisirs\": \"sport, musique, voyage\",\n      \"événements\": \"sorties avec les amis, soirées\"\n   }\n}', 0.303358, 0.110112, 80.5734),
(52, '7667085901872', 5, 'https://www.greats.com/products/the-kingston-blanco-navy-mens', 'Shoes', 'Sneakers', 'Greats', 'The Kingston - Blanco Navy', 'Introducing The Kingston, where old-school style meets the future of sneaker tech. Handcrafted in Portugal with rich premium goat leather that hugs and contours to your foot, its natural strength, flexibility, and lighter weight make these shoes the next best thing to being barefoot - unparalleled comfort right out of the box. Don\'t settle for less and see for yourself why these sneakers are ahead of the game.', 199.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/KING01SG-403_1.jpg?v=1757010317', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker avec un style incontournable', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"décontracté\"\n   ],\n   \"occasion_port\": [\n      \"sortie avec des amis\",\n      \"rendez-vous galant\",\n      \"jour de travail\"\n   ]\n}', 0.515126, 0.400522, 80.0452),
(53, '7667086000176', 5, 'https://www.greats.com/products/the-kingston-white-white-mens', 'Shoes', 'Sneakers', 'Greats', 'The Kingston - White White', 'Introducing The Kingston, where old-school style meets the future of sneaker tech. Handcrafted in Portugal with rich premium goat leather that hugs and contours to your foot, its natural strength, flexibility, and lighter weight make these shoes the next best thing to being barefoot - unparalleled comfort right out of the box. Don\'t settle for less and see for yourself why these sneakers are ahead of the game.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/KING01SG-L90_1.jpg?v=1757010318', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker avec un style incontournable', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Alexandra\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"activite\": \"urbaine\",\n      \"loisirs\": \"shopping, sorties avec les amis\",\n      \"mode_de_vie\": \"urbain, dynamique\"\n   },\n   \"traits_personnalite\": {\n      \"confiance\": \"élevée\",\n      \"ouverture\": \"ouverte\",\n      \"independance\": \"forte\",\n      \"sensibilite\": \"moyenne\"\n   },\n   \"occasion_port\": {\n      \"type_evenement\": \"sorties avec les amis, soirées\",\n      \"lieu\": \"ville, centre-ville\",\n      \"occasion\": \"rendez-vous, sortie en couple\"\n   }\n}', 0.515126, 0.400522, 80.0452),
(54, '7667086065712', 5, 'https://www.greats.com/products/the-reign-navy-mens', 'Shoes', 'Sneakers', 'Greats', 'The Reign - Navy', 'Meet the new classic. The Reign redefines the classic low-profile sneaker. Handcrafted in Portugal from premium Italian leather, waxed cotton laces, and natural rubber, it balances effortless style with a low environmental footprint. Minimalist, versatile, and timeless, it elevates every outfit—today, tomorrow, and beyond.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/REIG01SG-9UU_1.jpg?v=1757010654', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker avec un style incontournable', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain actif\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"ambitieux\"\n   ],\n   \"occasion_port\": [\n      \"rendez-vous professionnel\",\n      \"sortie avec des amis\",\n      \"événement social\"\n   ]\n}', 0.515126, 0.400522, 80.0452),
(55, '7667086426160', 5, 'https://www.greats.com/products/the-royale-2-0-burnished-cuoio-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Burnished Cuoio', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. A n evolved fit that feels impossibly comfortable right out of the box; gold foil branding details; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life.', 199.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYL01SG-200_1.jpg?v=1757012901', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker iconique avec un style incontournable', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"35-55\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": {\n      \"ambitieux\": 0.8,\n      \"confiant\": 0.7,\n      \"décontracté\": 0.6,\n      \"soigneux\": 0.9,\n      \"influencé par la mode\": 0.8\n   },\n   \"occasion_port\": {\n      \"travail\": 0.6,\n      \"sorties nocturnes\": 0.4,\n      \"événements spéciaux\": 0.3,\n      \"loisirs de luxe\": 0.2\n   }\n}', 0.515126, 0.400522, 80.0452),
(56, '7667086491696', 5, 'https://www.greats.com/products/the-royale-2-0-tonal-blush-womens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Tonal Blush', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. A n evolved fit that feels impossibly comfortable right out of the box; gold foil branding details; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYL02SG-671_1.jpg?v=1757013528', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker iconique avec un style incontournable', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain chic\",\n   \"traits_personnalite\": [\n      \"confiante\",\n      \"independante\",\n      \"styleuse\",\n      \"amoureuse de la mode\"\n   ],\n   \"occasion_port\": \"soirée, sortie avec des amis, rendez-vous\"\n}', 0.515126, 0.400522, 80.0452),
(57, '7667086557232', 5, 'https://www.greats.com/products/the-royale-knit-2-0-grey-white-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale Knit 2.0 - Grey White', 'Meet the new and improved version of our classic Royale Knit style - crafted with vegan materials and recycled plastic. It\'s lightweight, comfortable, and the featherweight knit upper retains the shoe’s classic silhouette while minimizing bulk. Best of all, the durable, flexible knit cleans as easily as it wears. Beat it up, wear it in, then simply rinse it out with some soap and water. Just like that, your new favorite adventure shoe is back on track.', 179.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYK01SG-IO5_1.jpg?v=1757013283', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Synthétique', 'Gomme', 'Lacets', 'homme', 'Sneaker en maille avec un style incontournable', 1, 81.1053, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confident\": 8,\n      \"independant\": 9,\n      \"éclectique\": 7,\n      \"prévisible\": 4\n   },\n   \"occasion_port\": {\n      \"journee_travail\": 6,\n      \"sortie_nuit\": 4,\n      \"activites_au_parc\": 3,\n      \"rendez-vous_professionnel\": 5\n   }\n}', 0.136972, 0.0659138, 81.0924),
(58, '7667086655536', 5, 'https://www.greats.com/products/the-royale-slip-on-2-0-blanco-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 Slip On - Blanco', 'A new spin on the shoe that started it all. The effortless cool look of the Royale 2.0, in an effortless slip-on fit. Already impossibly comfortable right out of the box, we replaced the shoelaces with a flexible elasticated panel to help you get out the door (or through airport security) faster. Our buttery smooth full grained leather and suede upper gives it a sleek new look that will carry you from weekend to workweek.', 199.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYS01SG-84D_1.jpg?v=1757013283', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Sneaker slip-on avec un style incontournable', 1, 80.0526, 3, '{\n  \"nom_persona\": \"Léo Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain actif\",\n   \"traits_personnalite\": {\n      \"confident\": 8,\n      \"independant\": 9,\n      \"éclectique\": 7,\n      \"passionné\": 8,\n      \"authentique\": 9\n   },\n   \"occasion_port\": {\n      \"jour de travail\": 4,\n      \"sortie avec les amis\": 6,\n      \"sortie romantique\": 2,\n      \"activités sportives\": 8,\n      \"événements de mode\": 5\n   }\n}', -0.296226, 0.575709, 80.0452),
(59, '7667086753840', 5, 'https://www.greats.com/products/the-royale-slip-on-2-0-sand-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 Slip On - Sand', 'A new spin on the shoe that started it all. The effortless cool look of the Royale 2.0, in an effortless slip-on fit. Already impossibly comfortable right out of the box, we replaced the shoelaces with a flexible elasticated panel to help you get out the door (or through airport security) faster. Our buttery smooth full grained leather and suede upper gives it a sleek new look that will carry you from weekend to workweek.', 199.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYS01SG-59N_1.jpg?v=1757013387', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Sneaker slip-on avec un style incontournable', 1, 80.0526, 3, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confident\": 8,\n      \"independant\": 7,\n      \"éclectique\": 9,\n      \"passionné\": 8,\n      \"conscientieux\": 6\n   },\n   \"occasion_port\": {\n      \"jour_né\": \"week-end\",\n      \"soirée\": \"occasionnelle\",\n      \"activité physique\": \"randonnée\",\n      \"sortie avec amis\": \"fréquente\"\n   }\n}', -0.296226, 0.575709, 80.0452),
(60, '7667086622768', 5, 'https://www.greats.com/products/the-royale-knit-2-0-panna-white-womens', 'Shoes', 'Sneakers', 'Greats', 'The Royale Knit 2.0 - Panna White', 'Meet the new and improved version of our classic Royale Knit style - crafted with vegan materials and recycled plastic. It\'s lightweight, comfortable, and the featherweight knit upper retains the shoe’s classic silhouette while minimizing bulk. Best of all, the durable, flexible knit cleans as easily as it wears. Beat it up, wear it in, then simply rinse it out with some soap and water. Just like that, your new favorite adventure shoe is back on track.', 179.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYK02SG-740_1.jpg?v=1757013529', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Synthétique', 'Gomme', 'Lacets', 'homme', 'Sneaker en maille avec un style incontournable', 1, 81.1053, 1, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain chic\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"independance\": 9,\n      \"sensibilité\": 7,\n      \"éclectisme\": 8,\n      \"authenticité\": 9\n   },\n   \"occasion_port\": {\n      \"journee_travail\": \"occasionnel\",\n      \"sortie_nuit\": \"frequente\",\n      \"activités_sportives\": \"occasionnel\",\n      \"réunion_amis\": \"frequente\",\n      \"événement_spécial\": \"occasionnel\"\n   }\n}', 0.136972, 0.0659138, 81.0924),
(61, '7585414971440', 5, 'https://www.greats.com/products/no-show-sock-blanco-copy', 'Shoes', 'Sneakers', 'Greats', 'Sneaker Wipes (12pcs)', 'Introducing NRS Industries Essential Sneaker Wipes: Your water based, on-the-move ally for swift sneaker sprucing. Every wipe features dual surfaces - smooth for gentle cleaning and textured for tougher spots. Ideal for leather, plastic, vinyl and rubber. Please avoid using on suede or nubuck. Includes 12 individually wrapped sneaker wipes.', 11.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/Rectangle883_021c3437-1c6f-4eb6-af9d-164fe76643c9.jpg?v=1763049968', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Synthétique', 'Gomme', 'Slip-on', 'unisexe', 'Nettoyage de chaussures en 12 morceaux', 1, 89.9474, 3, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-45\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"pratique\",\n      \"actif\",\n      \"soigneant\",\n      \"décontracté\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements sportifs\",\n      \"voyages\",\n      \"journées de shopping\"\n   ]\n}', -0.370438, 0.247633, 89.6937),
(62, '7585416970288', 5, 'https://www.greats.com/products/foam-sneaker-cleaner', 'Shoes', 'Sneakers', 'Greats', 'Foam Sneaker Cleaner', 'Introducing a revolutionary Sneaker Cleaning Foam: a potent blend of cleaning and conditioning agents in every pump, ensuring your sneakers receive the utmost care. Specially designed for quick and easy application, NRS Industries Essential Sneaker Cleaning Foam dispenses the ideal balance of solution to water, guaranteeing an effective clean every time. It\'s exceptionally well-suited for suede and nubuck materials, with no water required. This formula is safe on all materials, streamlining your sneaker care routine without the need for a bowl. The process is straightforward: pump, scrub, and wipe, facilitating a quick and hassle-free cleaning experience.', 11.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/Rectangle878_ad0c3964-40cb-4ed8-b65b-44db374bceaf.jpg?v=1763049741', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Synthétique', 'Gomme', 'Slip-on', 'unisexe', 'Nettoyage et protection de chaussures', 1, 89.9474, 3, '{\n  \"nom_persona\": \"Alex Chen\",\n   \"age_cible\": \"25-45\",\n   \"style_vie\": {\n      \"activite\": \"urbaine\",\n      \"loisirs\": [\"musique\", \"cinéma\", \"sorties\"],\n      \"mode_de_vie\": \"urbain\",\n      \"niveau_de_vie\": \"moyen\"\n   },\n   \"traits_personnalite\": {\n      \"priorites\": [\"qualité\", \"décoration\"],\n      \"attentes\": [\"efficacité\", \"satisfaction\"],\n      \"comportements\": [\"pratique\", \"écologique\"],\n      \"valeur\": [\"autonomie\", \"originalité\"]\n   },\n   \"occasion_port\": {\n      \"lieu\": [\"ville\", \"paysage urbain\"],\n      \"événement\": [\"sorties\", \"événements culturels\"],\n      \"activité\": [\"musique\", \"cinéma\", \"sport\"],\n      \"durée\": [\"courte\", \"moyenne\"]\n   }\n}', -0.370438, 0.247633, 89.6937),
(63, '7579963883568', 5, 'https://www.greats.com/products/the-ironside-nero-mens', 'Shoes', 'Sneakers', 'Greats', 'The Ironside - Nero', 'Introducing the Ironside, Greats latest masterpiece in suede. This sneaker is a tribute to the refined sophistication of a bygone era, reimagined for the modern gentleman. Inspired by the luxurious allure of smoking jackets and the rich, smooth notes of fine whisky, the Ironside exudes an elegance that\'s both timeless and contemporary. The color palette is as deep and inviting as a well-aged single malt, offering a perfect blend of tradition and trend. The Ironside is more than a sneaker; it\'s an experience, a statement of class and comfort. It\'s designed for those who appreciate the finer things in life and aren\'t afraid to show it.', 129.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/IRNL01SG-CUQ-01.jpg?v=1757015132', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'homme', 'Sneaker en toile avec style sophistiqué', 1, 83.6847, 1, '{\n  \"nom_persona\": \"Alexandre \'Lex\' Dumont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain, actif, sportif\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"independance\": 9,\n      \"ambition\": 7,\n      \"passion\": 8,\n      \"authenticite\": 9\n   },\n   \"occasion_port\": {\n      \"journee_travail\": \"occasionnel\",\n      \"sortie_nuit\": \"fréquent\",\n      \"activites_sportives\": \"fréquent\",\n      \"rendez-vous_amicaux\": \"fréquent\"\n   }\n}', 0.303358, 0.110112, 83.6556),
