(77, '7260205580336', 5, 'https://www.greats.com/products/the-royale-2-0-cuoio-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Cuoio', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. A n evolved fit that feels impossibly comfortable right out of the box; gold foil branding details; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life.', 199.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/RYLL01SG-IXF-01.jpg?v=1757015989', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'homme', 'Sneaker évoluée avec confort et style', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-45\",\n   \"style_vie\": {\n      \"activite\": \"urbaine\",\n      \"loisirs\": [\"musique\", \"cinéma\", \"voyages\"],\n      \"mode_de_vie\": \"urbain\"\n   },\n   \"traits_personnalite\": {\n      \"ambitieux\": true,\n      \"independant\": true,\n      \"élégant\": true,\n      \"conscientieux\": true\n   },\n   \"occasion_port\": {\n      \"occasion\": \"quotidienne\",\n      \"activite\": [\"travail\", \"sortie\"],\n      \"evenement\": [\"rendez-vous\", \"soirée\"]\n   }\n}', 0.303358, 0.110112, 80.0452),
