(79, '7279770894384', 5, 'https://www.greats.com/products/the-royale-2-0-triple-black-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Triple Black', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. A n evolved fit that feels impossibly comfortable right out of the box; gold foil branding details; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYL01SG-12O_1.jpg?v=1757012873', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'homme', 'Sneaker évoluée avec confort et style', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Kai\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"passionné par la mode\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements sportifs\",\n      \"rendez-vous amoureux\"\n   ]\n}', 0.303358, 0.110112, 80.0452),
(80, '7260194897968', 5, 'https://www.greats.com/products/the-royale-2-0-blanco-gold-womens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Blanco/Gold', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. A n evolved fit that feels impossibly comfortable right out of the box; gold foil branding details; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life in white sneakers for women .', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/GREATS-Womens-Royale2.0-Bncoco-01_Web_77b8cd8b-e89a-4628-a6f8-a19537ac6a2a.jpg?v=1757530970', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'femme', 'Sneaker évoluée avec confort et style', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain sophistiqué\",\n   \"traits_personnalite\": [\n      \"ambitieux\",\n      \"confiant\",\n      \"décontracté\",\n      \"passionné par la mode\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements de style\",\n      \"rendez-vous romantiques\",\n      \"photoshoots\"\n   ]\n}', 0.303358, 0.110112, 80.0452),
(81, '7260203089968', 5, 'https://www.greats.com/products/the-royale-2-0-blanco-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Blanco', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. A n evolved fit that feels impossibly comfortable right out of the box; embossed branding detail; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life. View our other white sneakers for men.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYL01SG-84D_1_decfcbe9-8839-4c71-8a1d-6e068215b9c7.jpg?v=1757011199', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker iconique avec un design évolutif et un confort imparable.', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confident\": true,\n      \"influencé\": true,\n      \"décontracté\": true,\n      \"tendance\": true,\n      \"élégant\": true\n   },\n   \"occasion_port\": {\n      \"jour_né\": \"soirée\",\n      \"week_end\": \"sortie\",\n      \"jour_travail\": \"réunion\",\n      \"événement\": \"fête\"\n   }\n}', 0.515126, 0.400522, 80.0452),
