(83, '7260206170160', 5, 'https://www.greats.com/products/the-royale-2-0-navy-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Navy', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. A n evolved fit that feels impossibly comfortable right out of the box; gold foil branding details; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life.', 199.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYL01SG-9UU_1.jpg?v=1757012936', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker iconique avec un design évolutif et des détails en or.', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Alexandre Dubois\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain actif\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"ambition\": 7,\n      \"independance\": 9,\n      \"sensibilité\": 5\n   },\n   \"occasion_port\": {\n      \"occasion\": \"soirée en ville\",\n      \"activité\": \"sortie avec des amis\",\n      \"lieu\": \"restaurant ou bar\"\n   }\n}', 0.515126, 0.400522, 80.0452),
(84, '7260200337456', 5, 'https://www.greats.com/products/the-royale-2-0-nero-mens', 'Shoes', 'Sneakers', 'Greats', 'The Royale 2.0 - Nero', 'Since the launch of our iconic sneaker, the Royale has been the epitome of effortless cool. But even icons have to change to stay rooted in the present—which is why we\'ve created the Royale 2.0. A n evolved fit that feels impossibly comfortable right out of the box; gold foil branding details; the return of our signature tack stitch; and plenty more upgrades you\'ll just have to discover for yourself. Welcome to the 2.0 side of life.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/ROYL01SG-CUQ_1.jpg?v=1757012889', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Sneaker iconique avec un design évolutif et des détails en or.', 1, 80.0526, 1, '{\n  \"nom_persona\": \"Aurélien\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confident\": true,\n      \"influencé\": true,\n      \"décontracté\": true,\n      \"élégant\": true,\n      \"déterminé\": true\n   },\n   \"occasion_port\": {\n      \"soirée\": true,\n      \"sortie\": true,\n      \"réunion\": true,\n      \"dîner\": true,\n      \"événement\": true\n   }\n}', 0.515126, 0.400522, 80.0452),
(85, '7201224458288', 5, 'https://www.greats.com/products/the-reign-blanco-womens', 'Shoes', 'Sneakers', 'Greats', 'The Reign - Blanco', 'Meet the new classic. Expertly handcrafted in Portugal from European materials—think premium quality leather, waxed cotton laces, and 100% natural rubber—our Reign sneaker is the women\'s white sneaker designed to rule your closet. It\'s a low-profile, low-environmental impact staple that effortlessly elevates just about any outfit—today, tomorrow, and forever.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/REIL02SG-84D-01.jpg?v=1757031726', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'femme', 'Sneaker classique en cuir de qualité supérieure.', 1, 80.0526, 3, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independant\",\n      \"tendance\",\n      \"amoureux de la mode\"\n   ],\n   \"occasion_port\": [\n      \"sortie avec des amis\",\n      \"rendez-vous galant\",\n      \"soirée en ville\",\n      \"événement de mode\"\n   ]\n}', -0.296226, 0.575709, 80.0452),
(86, '7184150429744', 5, 'https://www.greats.com/products/the-reign-blanco-mens', 'Shoes', 'Sneakers', 'Greats', 'The Reign - Blanco', 'Meet the new classic in iconic white sneakers . Expertly handcrafted in Portugal from locally sourced materials—think premium Italian leather, waxed cotton laces, and 100% natural rubber—our Reign sneaker is designed to rule your closet. It\'s a low-profile, low-environmental impact staple that effortlessly elevates just about any outfit—today, tomorrow, and forever.', 199.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/GREATS-Mens-Reign-Blanco-01_Web.jpg?v=1757531332', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'femme', 'Sneaker classique en cuir de qualité supérieure.', 1, 80.0526, 3, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"tendance\"\n   ],\n   \"occasion_port\": [\n      \"sortie avec les amis\",\n      \"rendez-vous galant\",\n      \"soirée en ville\"\n   ]\n}', -0.296226, 0.575709, 80.0452),
(87, '7184201547824', 5, 'https://www.greats.com/products/the-charlie-blanco-mens', 'Shoes', 'Sneakers', 'Greats', 'The Charlie - Blanco', 'Introducing Charlie: inspired by the sporty styles worn by footballers the world over, but polished up and elevated with buttery soft—yet strong—premium Italian leather and natural rubber. Our version is handmade in Italy by expert craftsmen, using the finest locally sourced materials for a lighter environmental footprint that scores big on every level. In a word? GOAL. Browse our signature white sneakers line .', 128.97, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0238/2821/files/GCHARLI0-84D_1.jpg?v=1757009667', '2026-03-24 16:32:33', '2026-03-24 16:32:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Sneaker sportive en cuir de qualité supérieure.', 1, 83.7384, 3, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confident\": true,\n      \"independant\": true,\n      \"tendre\": false,\n      \"excentrique\": true\n   },\n   \"occasion_port\": {\n      \"soirée\": true,\n      \"sortie avec amis\": true,\n      \"rendez-vous\": false,\n      \"jour de travail\": false\n   }\n}', -0.296226, 0.575709, 83.704),
(88, '7671893557317', 3, 'https://taftclothing.com/products/the-rome-dress-boot-in-brown-croco', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Rome Boot in Brown Croco', 'The Rome Boot in Rich Brown Croco exists because not all croco is built on leather capable of carrying it. It begins in the hands of heritage Italian artisans, who select each hide based on density, grain integrity, and its ability to hold definition through years of wear — then finish it using techniques designed to preserve structure while allowing the material to develop depth over time. The deep embossed croco pattern is then pressed directly into the leather while it’s still responsive, creating texture that lives within the material rather than sitting on the surface — keeping edges crisp and scales dimensional as the leather wears. As it ages, the embossing softens naturally, creating deeper dimension while maintaining its structure. Crafted with Blake stitch construction, a hand-cut leather welt, and a lug outsole with rubber pods to increase traction, this boot reflects the signature Taft commitment to craftsmanship—built for enduring style, confident comfort, and years of wear. Inside, a custom padded insole—German engineered for advanced climate control—actively wicks away moisture and features an integrated anti-microbial compound to maintain freshness throughout the day. Designed for performance beneath the surface, it keeps you dry, ventilated, and consistently comfortable from first step to last This is the version of croco chosen by men who understand materials, not just fashion. And prefer presence without performance.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/ROME-CBN_WEB1.jpg?v=1762447711', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'homme', 'Botte en toile de croco de haute qualité.', 1, 72.1579, 1, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"28-45\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": [\n      \"confident\",\n      \"independante\",\n      \"appreciative de la qualité\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"rendez-vous\",\n      \"week-ends en ville\"\n   ]\n}', 0.303358, 0.110112, 72.2005),
(89, '7920588587077', 3, 'https://taftclothing.com/products/the-jack-penny-loafer-in-washed-denim-floral', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Jack Penny Loafer in Washed Denim Floral', 'The Jack doesn\'t follow, it leads. Handcrafted from genuine leather with a comfort footbed that moves with you, The Jack loafer is where classic penny loafer heritage meets modern swagger. The slip-on design keeps things smooth, while the round toe and block heel add substance without sacrificing sleek. This isn\'t your grandfather\'s penny loafer. It\'s sharper, bolder, and built to turn heads on city streets or corner offices. The leather lining whispers luxury with every step, and that 1 1/4-inch heel? Just enough lift to command attention. Designed in the details, worn with intention.', 299.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/JACKLOAFER-WDF_WEB1.jpg?v=1767141672', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Loafer en cuir de qualité supérieure.', 1, 74.7374, 3, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Bohème Chic\",\n   \"traits_personnalite\": {\n      \"ouverture\": 8,\n      \"éclectisme\": 9,\n      \"conformisme\": 2,\n      \"influence\": 6\n   },\n   \"occasion_port\": {\n      \"jour\": {\n         \"soirée\": 7,\n         \"dîner\": 6,\n         \"sortie avec amis\": 8\n      },\n      \"week-end\": {\n         \"promenade\": 9,\n         \"sortie en ville\": 8,\n         \"week-end en famille\": 5\n      }\n   }\n}', -0.296226, 0.575709, 74.7631),
(90, '7929525403717', 3, 'https://taftclothing.com/products/the-lewis-boot-in-black-floral', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Lewis Boot in Black Floral', 'Our Lewis Boot, reimagined in Italy. We took luxury Italian materials and upgraded the fit, comfort, and styling of the Lewis. If you\'ve worn TAFT before, come feel the difference. If this is your first time, come experience TAFT at its best.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/LEWIS-BFL_WEB1.jpg?v=1768413035', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Botte en cuir de qualité supérieure.', 1, 72.1579, 1, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Bohème Chic\",\n   \"traits_personnalite\": {\n      \"ouverture\": 8,\n      \"curiosité\": 9,\n      \"éclectisme\": 8,\n      \"individualisme\": 7,\n      \"sensibilité\": 9\n   },\n   \"occasion_port\": {\n      \"jour de semaine\": \"rendez-vous avec des amis\",\n      \"week-end\": \"sorties en ville ou dans la nature\",\n      \"événements spéciaux\": \"fêtes de fin d\'année ou anniversaires\"\n   }\n}', 0.515126, 0.400522, 72.2005),
(91, '7929535758405', 3, 'https://taftclothing.com/products/the-lewis-boot-in-brown-floral', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Lewis Boot in Brown Floral', 'Our Lewis Boot, reimagined in Italy. We took luxury Italian materials and upgraded the fit, comfort, and styling of the Lewis. If you\'ve worn TAFT before, come feel the difference. If this is your first time, come experience TAFT at its best.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/LEWIS-BRF_WEB1.jpg?v=1768413190', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Botte en cuir de qualité supérieure.', 1, 72.1579, 1, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Bohème Chic\",\n   \"traits_personnalite\": {\n      \"ouverture\": 8,\n      \"curiosité\": 9,\n      \"éclectisme\": 8,\n      \"originalité\": 7,\n      \"authenticité\": 9\n   },\n   \"occasion_port\": {\n      \"jour de semaine\": \"rendez-vous avec des amis\",\n      \"week-end\": \"sortie en ville ou en nature\",\n      \"événement spécial\": \"fête de style ou événement culturel\"\n   }\n}', 0.515126, 0.400522, 72.2005),
(92, '7929618432069', 3, 'https://taftclothing.com/products/the-russell-in-chocolate-floral-suede', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Russell in Chocolate Floral Suede', 'The Russell bit loafer by TAFT showcases a bold, classic style with striking hardware detail. Crafted from genuine leather, it is enhanced with elegant Jacquard accents around the ankle.', 299.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/RUSSELL-CFS_WEB1.jpg?v=1768419548', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Loafer en cuir de qualité supérieure.', 1, 74.7374, 1, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain chic\",\n   \"traits_personnalite\": [\n      \"indépendante\",\n      \"créative\",\n      \"éclectique\",\n      \"appreciative de la qualité\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements de mode\",\n      \"rendez-vous romantiques\",\n      \"photographies de mode\"\n   ]\n}', 0.515126, 0.400522, 74.7631),
(93, '7920588062789', 3, 'https://taftclothing.com/products/the-tommy-in-duskwood-floral', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Tommy in Duskwood Floral', 'Inspired by the warm glow of sunset over Florence, it\'s loom-woven jacquard upper captures depth, movement, and color in a way traditional prints simply can’t. Each pattern is woven directly into the fabric, not applied, creating a dimensional surface that feels as rich as it looks. The floral motifs shift subtly in light, echoing the layered tones of terracotta rooftops and golden-hour skies. Set on a refined tassel loafer silhouette, the Tommy blends old-world craftsmanship with relaxed elegance. Blake stitching keeps the profile sleek and flexible while allowing for resoling—a construction choice made for longevity, not just appearance. Finished with a German-engineered cushioned footbed with anti-microbial protection—so the comfort stays discreet, and the wear stays fresh from day to night. This is the kind of piece chosen by those who travel well—even when they’re standing still. Artful. Intentional. Effortless.', 299.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/TOMMY-DWF_WEB1.jpg?v=1767141341', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Loafer en cuir de qualité supérieure.', 1, 74.7374, 3, '{\n  \"nom_persona\": \"Luna Nightingale\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Bohème Éclectique\",\n   \"traits_personnalite\": [\n      \"Créative\",\n      \"Indépendante\",\n      \"Aventureuse\",\n      \"Sensuelle\",\n      \"Authentique\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Fêtes et événements\",\n      \"Week-ends en ville\",\n      \"Dates romantiques\",\n      \"Photographies de mode\"\n   ]\n}', -0.296226, 0.575709, 74.7631),
(94, '7632564977733', 3, 'https://taftclothing.com/products/the-rome-dress-boot-in-black-croco', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Rome Boot in Black Croco', 'The Rome Black Croco exists because not all croco is built on leather capable of carrying it. It begins in the hands of heritage Italian artisans, who select each hide based on density, grain integrity, and its ability to hold definition through years of wear — then finish it using techniques designed to preserve structure while allowing the material to develop depth over time. The deep embossed croco pattern is then pressed directly into the leather while it’s still responsive, creating texture that lives within the material rather than sitting on the surface — keeping edges crisp and scales dimensional as the leather wears. As it ages, the embossing softens naturally, creating deeper dimension while maintaining its structure. Crafted with Blake stitch construction, a hand-cut leather welt, and a lug outsole with rubber pods to increase traction, this boot reflects the signature Taft commitment to craftsmanship—built for enduring style, confident comfort, and years of wear. Inside, a custom padded insole—German engineered for advanced climate control—actively wicks away moisture and features an integrated anti-microbial compound to maintain freshness throughout the day. Designed for performance beneath the surface, it keeps you dry, ventilated, and consistently comfortable from first step to last This is the version of croco chosen by men who understand materials, not just fashion. And prefer presence without performance.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/ROME-CBK_WEB1.jpg?v=1762447699', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'homme', 'Botte en toile de croco de haute qualité.', 1, 72.1579, 1, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"28-45\",\n   \"style_vie\": \"urbain-chic\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"independance\": 9,\n      \"sensibilité\": 6,\n      \"authenticité\": 8\n   },\n   \"occasion_port\": {\n      \"journee_travail\": 7,\n      \"sortie_nuit\": 6,\n      \"weekend\": 8,\n      \"événement_spécial\": 5\n   }\n}', 0.303358, 0.110112, 72.2005),
(95, '7920579018821', 3, 'https://taftclothing.com/products/the-lewis-boot-in-dark-brown', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Lewis Boot in Dark Brown', 'For the man who notices leather before logos, the Lewis Dark Brown is crafted by Italian artisans, made from smooth full-grain calfskin sourced and hand-finished in Italy, preserving the natural grain layer where the strongest fibers live. The high-oil pull-up leather is designed for real wear — flexing naturally, resisting dryness, and developing tonal movement as oils shift through the leather over time. The smooth surface allows the leather’s natural depth and patina development to show fully, creating a rugged, broken-in character that improves through use rather than wearing out. Built on one of our best-selling silhouettes, the Lewis delivers a rugged look anchored in classic, everyday versatility. The result is simple: The more you wear the Lewis, the better it looks — because real leather remembers. And over time, ownership leaves a signature.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/LEWIS-DBR_WEB1.jpg?v=1767140742', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Botte en cuir de qualité supérieure.', 1, 72.1579, 1, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"28-45\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"conscient\": true,\n      \"independent\": true,\n      \"éclectique\": true,\n      \"préoccupé par la qualité\": true\n   },\n   \"occasion_port\": {\n      \"jour de travail\": true,\n      \"sorties nocturnes\": true,\n      \"week-end en ville\": true,\n      \"événements spéciaux\": true\n   }\n}', 0.515126, 0.400522, 72.2005),
(96, '7920571285573', 3, 'https://taftclothing.com/products/the-dylan-jodhpur-boot-in-brown', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Dylan Jodhpur Boot in Brown', 'Introducing the Dylan Jodhpur Brown, most boots try to look finished on day one. The Dylan is designed to peak years into ownership. The upper uses hand-burnished, full grain Italian leather, with deep saturated color. It’s built slowly, by hand, ensuring the leather evolves with movement, pressure, and time. At the back, the Italian suede is shaved slower and brushed finer to create a dense, controlled nap that moves with the ankle while holding its structure. Instead of breaking down, it adapts — molding faster, softening where you flex, maintaining strength where you don’t. Crafted with Blake stitch construction, a hand-cut leather welt, and a rugged lug outsole, this boot reflects the signature Taft commitment to craftsmanship—built for enduring style, confident comfort, and years of wear. Built for men who measure value in decades, not seasons.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/DYLAN-BRN_WEB1.jpg?v=1767140255', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Botte en cuir de qualité supérieure.', 1, 72.1579, 1, '{\n  \"nom_persona\": \"Emily Wilson\",\n   \"age_cible\": \"28-45\",\n   \"style_vie\": \"Rustique Chic\",\n   \"traits_personnalite\": [\n      \"Indépendante\",\n      \"Ambitieuse\",\n      \"Appréciatrice de la nature\"\n   ],\n   \"occasion_port\": [\n      \"Sorties en ville\",\n      \"Week-ends en campagne\",\n      \"Réunions avec des amis\"\n   ]\n}', 0.515126, 0.400522, 72.2005),
(97, '7671940317253', 3, 'https://taftclothing.com/products/the-glen-boot-in-taupe-croco', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Glen Boot in Taupe Croco', 'The Glen Chelsea Boot — Handmade in Italy for the man who knows refinement doesn’t need to shout. Smooth, full-grain leather shapes a clean Chelsea profile with a classic round toe for understated polish. The slip-on design gives you instant readiness, while the leather molds to you over time—gaining character with every wear. A durable rubber outsole keeps you grounded, season after season.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/GLEN-CTA_WEB1.jpg?v=1762447714', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Botte en cuir de qualité supérieure.', 1, 72.1579, 3, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"28-45\",\n   \"style_vie\": \"urbain-chic\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"independance\": 9,\n      \"sensibilité\": 7,\n      \"éclectisme\": 8,\n      \"authenticité\": 9\n   },\n   \"occasion_port\": {\n      \"journee_travail\": 6,\n      \"sortie_nuit\": 4,\n      \"week-end\": 8,\n      \"réunion_sociale\": 7,\n      \"événement_spécial\": 5\n   }\n}', -0.296226, 0.575709, 72.2005),
(98, '4351355093061', 3, 'https://taftclothing.com/products/the-hiro-boot-in-honey', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Hiro Chelsea Boot in Honey (Last Chance, Final Sale)', 'based on the classic Chelsea style. They are an easy pull-on and off shoe perfect for any event. The upper material has been constructed from boxcalf leather from Italy, while the counter is then constructed from a full grain leather that uniquely features an embossed croc detailing. With that interior completely lined with natural calfskin, the sole unit is stacked leather with a rubber insert. They easily become an instant favorite having them made with Blake Construction.', 249.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/Taft_OnWhite_20191114_2407-min.jpg?v=1762439548', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Botte en cuir de qualité supérieure.', 1, 77.3689, 3, '{\n  \"nom_persona\": \"Alexandra\",\n   \"age_cible\": \"28-45\",\n   \"style_vie\": \"élégante et sophistiquée\",\n   \"traits_personnalite\": [\n      \"confiante\",\n      \"independante\",\n      \"appreciative de la qualité\",\n      \"préoccupée par l\'élégance\"\n   ],\n   \"occasion_port\": [\n      \"rendez-vous professionnel\",\n      \"sortie en ville\",\n      \"soirée de gala\",\n      \"week-end en campagne\"\n   ]\n}', -0.296226, 0.575709, 77.3803),
(99, '7634272583749', 3, 'https://taftclothing.com/products/the-murphy-chelsea-boot-in-black', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Murphy Chelsea Boot in Black', 'The Murphy Chelsea Boot — Handmade in Italy for the man who refuses to blend in. Smooth genuine leather shapes a timeless Chelsea silhouette, while subtle floral detailing on the elastic gore adds just enough personality to turn a second glance into a conversation. The slip-on design delivers instant polish without the effort, and the classic round toe keeps it versatile from boardroom to bar. A leather outsole completes the refined finish—built to carry you for years.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/MURPHY-BLK_WEB1.jpg?v=1762447701', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Botte en cuir de qualité supérieure.', 1, 72.1579, 3, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": \"35-45\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": {\n      \"ambitieux\": true,\n      \"conformiste\": false,\n      \"sensible à la mode\": true,\n      \"appreciate la qualité\": true\n   },\n   \"occasion_port\": {\n      \"jour\": {\n         \"travail\": true,\n         \"sortie avec des amis\": true\n      },\n      \"soir\": {\n         \"dîner en ville\": true,\n         \"événement social\": true\n      }\n   }\n}', -0.296226, 0.575709, 72.2005),
