(143, '7406370652229', 3, 'https://taftclothing.com/products/the-rome-boot-in-noir-viejo', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Rome Boot in Noir Viejo', 'Say hello to the Rome Boot in Noir Viejo from TAFT—a masterpiece of hand-burnished floral embossing that feels like walking on art. With a studded rubber outsole, it’s as bold as it is dependable.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/BT-ROME-NVJ_TAFT1.jpg?v=1762447390', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Botte en cuir noir', 1, 72.1579, 2, '{\n  \"nom_persona\": \"Léonard\",\n   \"age_cible\": \"28-45\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confiant\": true,\n      \"indépendant\": true,\n      \"élégant\": true,\n      \"prévisible\": false\n   },\n   \"occasion_port\": {\n      \"jour\": {\n         \"travail\": true,\n         \"sortie\": true,\n         \"loisirs\": true\n      },\n      \"soir\": {\n         \"sortie\": true,\n         \"dîner\": true,\n         \"evenement\": true\n      }\n   }\n}', 0.460434, -0.413131, 72.2005),
(144, '7115979784261', 3, 'https://taftclothing.com/products/the-dylan-jodhpur-boot-in-chocolate', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Dylan Jodhpur Boot in Chocolate', 'The Dylan Jodhpur Boot in Chocolate from TAFT is a city-style suede men’s boot that epitomizes enduring appeal and rugged reliability. Featuring a leather sole complemented by rubber inserts, it ensures steadfast traction while exuding understated class. Designed with a standard D width, it seamlessly prioritizes comfort and style. Crafted using Blake construction in Spain, these boots promise longevity and effortless adaptability, making them an essential addition to any wardrobe.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/BT-DYLAN-CHOCOLATE_TAFT1.jpg?v=1762447335', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Toile', 'Caoutchouc', 'Lacets', 'homme', 'Botte en toile chocolat', 1, 72.1579, 2, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"28-45\",\n   \"style_vie\": \"Rustique Chic\",\n   \"traits_personnalite\": {\n      \"ambitieux\": 0.8,\n      \"independent\": 0.9,\n      \"éclectique\": 0.7,\n      \"passionné\": 0.6,\n      \"authentique\": 0.8\n   },\n   \"occasion_port\": {\n      \"journée\": {\n         \"travail\": 0.4,\n         \"sortie avec amis\": 0.3,\n         \"shopping\": 0.2\n      },\n      \"soirée\": {\n         \"dîner en ville\": 0.5,\n         \"événement social\": 0.4,\n         \"sortie romantique\": 0.1\n      }\n   }\n}', 0.293006, -0.522899, 72.2005),
