(147, '7010775695429', 3, 'https://taftclothing.com/products/the-douglas-boot-in-olive', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Douglas Boot in Olive (Last Chance, Final Sale)', 'The Douglas Boot in Olive from TAFT in Brown smoothly takes you from the office to nightlife, catering to an urban lifestyle with its versatile design. This men\'s boot is designed with a full-grain leather upper, which offers durability and a polished aesthetic. Incorporating suede on the ankle and collar adds a touch of class to its overall appearance. With a leather-lined interior and a comfortable crepe rubber outsole, the Douglas Boot offers style and ensures a pleasant experience for extended wear.', 129.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/BT-DOUGLAS-OLIVE_TAFT1.jpg?v=1762447310', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Botte en cuir olive', 1, 83.6847, 2, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": 35,\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"ambitieux\": 0.8,\n      \"indépendant\": 0.7,\n      \"éclectique\": 0.9,\n      \"pragmatique\": 0.6\n   },\n   \"occasion_port\": {\n      \"travail\": 0.4,\n      \"sortie avec les amis\": 0.3,\n      \"rendez-vous amoureux\": 0.2,\n      \"loisirs\": 0.1\n   }\n}', 0.460434, -0.413131, 83.6556),
