(151, '7010757967941', 3, 'https://taftclothing.com/products/the-boston-boot-in-whiskey', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Boston Boot in Whiskey (Last Chance, Final Sale)', 'The Boston Boot in Whiskey from TAFT captures the essence of the iconic long-wing brogue style, creating a moment of class. Featuring a full-grain leather upper complemented by suede, the boot fuses traditional craftsmanship with a contemporary look. Its leather-lined interior enhances comfort and style, while the rubber commando sole provides reliable traction for various terrains. The Blake-stitched construction adds to the boot\'s allure, making the Boston men\'s boot a refined choice for those seeking luxury in their urban adventures.', 129.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/BT-BOSTON-WHISKEY_TAFT1.jpg?v=1762447304', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Botte en cuir whiskey', 1, 83.6847, 2, '{\n  \"nom_persona\": \"Jack Harris\",\n   \"age_cible\": \"35-45\",\n   \"style_vie\": \"Rustique et urbain\",\n   \"traits_personnalite\": [\n      \"Indépendant\",\n      \"Confident\",\n      \"Avec un goût pour la qualité\",\n      \"Apprécie la simplicité\"\n   ],\n   \"occasion_port\": \"Sorties avec les amis, week-ends en ville, soirées informelles\"\n}', 0.460434, -0.413131, 83.6556),
(152, '7010730344517', 3, 'https://taftclothing.com/products/the-alpine-boot-in-honey', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Alpine Boot in Honey (Last Chance, Final Sale)', 'The Alpine Boot in Honey from TAFT is a rugged and bold choice for an all-weather shoe, ideally suited for your wild outdoor endeavors. With a unique hairy suede upper complemented by full-grain leather, the boot not only exudes a sense of class but also promises resilience in challenging conditions. Its leather lining ensures a comfortable experience, while the rubber ripple sole delivers excellent traction and enhances the overall durability of this men\'s boot.', 149.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/BT-ALPINE-HONEY_TAFT1_a4a267c8-d1a7-4a46-93a2-4777b8272343.jpg?v=1762447294', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Toile', 'Caoutchouc', 'Lacets', 'homme', 'Botte en toile miel', 1, 82.6321, 2, '{\n  \"nom_persona\": \"Lily Thompson\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Outdoor Enthusiast\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"independance\": 9,\n      \"passion\": 8,\n      \"authenticite\": 9,\n      \"éclectisme\": 7\n   },\n   \"occasion_port\": {\n      \"type\": \"Sortie\",\n      \"frequente\": \"Festival de musique\",\n      \"lieu\": \"Montagne\",\n      \"activite\": \"Randonnée\"\n   }\n}', 0.293006, -0.522899, 82.6141);
