(153, '7010730672197', 3, 'https://taftclothing.com/products/the-alpine-boot-in-peanut', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Alpine Boot in Peanut (Last Chance, Final Sale)', 'The Alpine Boot in Peanut from TAFT is a rugged and bold choice for an all-weather shoe, ideally suited for your wild outdoor endeavors. With a unique hairy suede upper complemented by full-grain leather, the boot not only exudes a sense of class but also promises resilience in challenging conditions. Its leather lining ensures a comfortable experience, while the rubber ripple sole delivers excellent traction and enhances the overall durability of this men\'s boot.', 149.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/BT-ALPINE-PEANUT_TAFT1_46b52e43-56a3-4e65-aaf5-625be1210693.jpg?v=1762447295', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Toile', 'Caoutchouc', 'Lacets', 'homme', 'Botte en toile noisette', 1, 82.6321, 2, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Outdoor\",\n   \"traits_personnalite\": {\n      \"adjectifs\": [\"ambitieux\", \"independent\", \"écologique\"],\n      \"hobbies\": [\"randonnée\", \"escalade\", \"cycling\"],\n      \"valeurs\": [\"qualité\", \"durabilité\", \"innovation\"]\n   },\n   \"occasion_port\": {\n      \"lieu\": \"montagne\",\n      \"activité\": \"randonnée\",\n      \"sexe\": \"masculin\",\n      \"âge\": \"25-35\"\n   }\n}', 0.293006, -0.522899, 82.6141),
