(174, '6962350784581', 3, 'https://taftclothing.com/products/the-viking-boot-in-black-velour', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Viking Boot in Black Velour (Last Chance, Final Sale)', 'Rugged meets refined in our latest Viking Boot, expertly crafted with a mix of textures and materials. Built with Blake Stitch construction, a plush velvet upper, calfskin ankle, and suede tongue, this wholly unique boot in Black Velour also features a Vibram Commando rubber sole for unmatched durability and traction. Handcrafted in Spain using high quality materials, this versatile boot is perfect for the modern adventurer looking for functionality, form, and a touch of sophistication.', 99.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/BT-VIKING-BLACKVELOUR_TAFT1.jpg?v=1762447271', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'homme', 'Botte en toile avec semelle en caoutchouc', 1, 85.2637, 1, '{\n  \"nom_persona\": \"Kai Ragnvaldsson\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"Rustique Chic\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"independance\": 9,\n      \"sens de l\'humour\": 7,\n      \"passion\": 8,\n      \"authenticité\": 9\n   },\n   \"occasion_port\": \"Sortie avec les amis, Week-end en montagne\"\n}', 0.303358, 0.110112, 85.2211),
