(193, '8747140294', 3, 'https://taftclothing.com/products/the-jack-boot-in-grey-brown', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Jack in Grey/Brown', 'Meet The Jack in Grey/Brown. This boot has quickly become our signature product. The calfskin inner-lining helps support and add structure to the 100% wool upper. The sole unit is leather with rubber inserts for added grip, durability, and comfort. This is a versatile boot, ranging from formal attire to casual wear. We spared no expense on this boot and the comfort and quality will show from the moment you put them on.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/jack_Grey_brown_DARKENED_02-min.jpg?v=1762439469', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Calfskin leather', 'Leather with rubber inserts', 'Slip-on', 'homme', 'Botte en calfskin leather, calfskin inner-lining', 1, 72.1579, 0, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"25-45\",\n   \"style_vie\": \"urbain, sophistiqué, actif\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independant\",\n      \"décontracté\",\n      \"éclectique\"\n   ],\n   \"occasion_port\": [\n      \"rendez-vous\",\n      \"sorties nocturnes\",\n      \"événements sociaux\",\n      \"jour de travail\"\n   ]\n}', -0.479304, -0.197569, 72.2005),
(194, '154270040085', 3, 'https://taftclothing.com/products/the-jack-shoe-in-grey-brown', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Jack Shoe in Grey/Brown', 'Meet The Jack Shoe in Grey/Brown. After countless requests to make our most popular boot in a shoe, we finally did it. This shoe is fit for the office or the weekend. Guaranteed to stand out and get you the attention you deserve.', 299.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/Taft_OnWhite_20171021_0007-min.jpg?v=1762439477', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Calfskin leather', 'Leather with rubber inserts', 'Slip-on', 'homme', 'Chaussure confortable, sol en cuir avec inserts en caoutchouc', 1, 74.7374, 0, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": \"25-45\",\n   \"style_vie\": \"urbain-chic\",\n   \"traits_personnalite\": {\n      \"ambitieux\": 0.8,\n      \"independent\": 0.7,\n      \"éclectique\": 0.9,\n      \"conscientieux\": 0.6\n   },\n   \"occasion_port\": {\n      \"jour\": 0.4,\n      \"soirée\": 0.3,\n      \"week-end\": 0.2,\n      \"travail\": 0.1\n   }\n}', -0.479304, -0.197569, 74.7631),
(195, '6697160671301', 3, 'https://taftclothing.com/products/the-mack-boot-in-brown', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Mack Boot in Brown (Last Chance, Final Sale)', 'Meet the Mack Boot in Brown. This is an instant classic. A full brogue, seven eyelet wingtip combat boot on a stacked leather sole. All of the pieces of the Mack Boot are cut by hand (rather than by machine or laser), highlighting the craftsmanship and pride that goes into making our shoes.', 119.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/BT-MACK-BROWN_TAFT1.jpg?v=1762441096', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Calfskin leather', 'Stacked leather sole', 'Scratch', 'homme', 'Botte en calfskin leather, full brogue, sept yeux', 1, 84.2111, 4, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": \"35-45\",\n   \"style_vie\": \"Rustique Chic\",\n   \"traits_personnalite\": [\n      \"Ambitieux\",\n      \"Confiant\",\n      \"Authentique\"\n   ],\n   \"occasion_port\": \"Jour de travail, Week-end en ville\"\n}', -0.326863, -0.318694, 84.1888),
(196, '6697158344773', 3, 'https://taftclothing.com/products/the-jack-boot-in-taupe-paisley', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Jack in Taupe Paisley', 'Meet The Jack in Taupe Paisley. This boot has quickly become our signature product. The sole unit is leather with rubber inserts for added grip, durability, and comfort. This is a versatile boot, ranging from formal attire to casual wear. We spared no expense on this boot and the comfort and quality will show from the moment you put them on.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/313A6454-2048px.jpg?v=1762441093', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Calfskin leather', 'Leather with rubber inserts', 'Slip-on', 'homme', 'Botte en calfskin leather, hand-burnished floral embossing', 1, 72.1579, 0, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"28-35\",\n   \"style_vie\": \"urbain-chic\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"originalité\": 9,\n      \"éclectisme\": 7,\n      \"sensibilité\": 6,\n      \"independance\": 8\n   },\n   \"occasion_port\": {\n      \"journee_travail\": 6,\n      \"sortie_nuit\": 4,\n      \"weekend\": 8,\n      \"événement_spécial\": 5\n   }\n}', -0.479304, -0.197569, 72.2005),
