(198, '6104297030', 3, 'https://taftclothing.com/products/the-jude-boot-tonal', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Jude Boot in Tonal (Last Chance, Final Sale)', 'Meet the Jude Chelsea Boot in tonal elastic. This boot will grab you the attention you deserve. The upper is made of high-quality, Spanish suede tanned and milled in Almansa, Spain. The sole unit is double-stacked, full-grain leather with rubber inserts for added grip, durability, and comfort. This is a versatile boot, ranging from formal attire to casual wear. The inner leather lining is paired with a cushioned airbed for your foot to make sure you are stylish and comfortable.', 249.99, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/wc_TaftOnWhite_20160428_9177_grande_605f127f-71f5-44ab-aa24-87d7d6c38b61.jpg?v=1762439466', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Spanish suede', 'Double-stacked, full-grain leather', 'Slip-on', 'homme', 'Botte en suede espagnol, tonal elastic', 1, 77.3689, 4, '{\n  \"nom_persona\": \"Alexandra\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"independante\": true,\n      \"confiante\": true,\n      \"éclectique\": true,\n      \"appreciative de la qualité\": true\n   },\n   \"occasion_port\": {\n      \"jour de travail\": true,\n      \"sortie avec des amis\": true,\n      \"rendez-vous romantique\": false,\n      \"événement spécial\": true\n   }\n}', -0.476829, -0.190724, 77.3803),
