(200, '4634446954565', 3, 'https://taftclothing.com/products/the-lucca-monk-shoe-in-honey-floral', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Lucca Monk Shoe in Honey Floral', 'Meet the Lucca Monk Shoe in Honey Floral. This is a captoe with Blake stitch construction. We love this take on a classic double monk strap with an unexpected twist. You will grab attention whenever you wear this shoe.', 299.99, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/files/SH-LUCCA-HONFLR_TAFT1_004f4b6b-6552-4a33-a276-67ade36a8763.jpg?v=1762439578', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Calfskin leather', 'Blake stitch construction', 'Scratch', 'homme', 'Chaussure en calfskin leather, captoe avec Blake stitch', 1, 74.7374, 4, '{\n  \"id\": \"LUCCA_MONK_SHOE_HONEY_FLORAL\",\n   \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"Bohème Chic\",\n   \"traits_personnalite\": [\n      \"Créative\",\n      \"Indépendante\",\n      \"Appréciatrice de la mode\",\n      \"Amoureuse de la nature\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Réunions avec des amis\",\n      \"Week-ends en ville\",\n      \"Événements de mode\"\n   ]\n}', -0.253427, -0.291969, 74.7631),
(201, '4634446495813', 3, 'https://taftclothing.com/products/the-jack-shoe-in-eden', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Jack Shoe in Eden Cognac', 'Meet The Jack Shoe in Eden from TAFT: where bold meets breathtaking. Crafted from cotton jacquard with intricate woven patterns, it’s the shoe that whispers, \"Why blend in when you can stand out?\"', 299.99, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/313A3838-2048px.jpg?v=1762439578', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cotton jacquard', 'Plateforme', 'Lacets', 'homme', 'Chaussure avec motifs intriqués', 1, 74.7374, 4, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": \"35-45\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": {\n      \"ambitieux\": true,\n      \"independent\": true,\n      \"appreciate la qualité\": true,\n      \"sensible à l\'élégance\": true\n   },\n   \"occasion_port\": {\n      \"jour de travail\": true,\n      \"sorties nocturnes\": true,\n      \"week-end en ville\": true,\n      \"événements spéciaux\": true\n   }\n}', -0.048211, -0.279768, 74.7631),
(202, '4520685142085', 3, 'https://taftclothing.com/products/the-preston-in-eden', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Preston Shoe in Eden Cognac', 'With its longwing brogue design, the Preston in Eden from TAFT is the epitome of comfort that doesn’t shy away from making an impression. The Preston effortlessly marries timeless elegance with a riot of floral charm.', 299.99, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/313A2924-2048px.jpg?v=1762439558', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cotton jacquard', 'Plateforme', 'Lacets', 'homme', 'Brogue longwing avec design élégant', 1, 74.7374, 4, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": \"35-50\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": {\n      \"ambitieux\": 8,\n      \"confiant\": 7,\n      \"influencé par les tendances\": 9,\n      \"appreciate la qualité\": 8,\n      \"préoccupé par l\'image\": 7\n   },\n   \"occasion_port\": {\n      \"travail\": {\n         \"frequent\": true,\n         \"occasion\": \"réunions d\'affaires, conférences\"\n      },\n      \"sortie\": {\n         \"frequent\": true,\n         \"occasion\": \"dîners, événements sociaux\"\n      },\n      \"loisirs\": {\n         \"frequent\": false,\n         \"occasion\": \"sorties avec les amis, weekend en ville\"\n      }\n   }\n}', -0.048211, -0.279768, 74.7631),
(203, '4519522566213', 3, 'https://taftclothing.com/products/the-rome-boot-in-navy', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Rome Boot in Navy (Last Chance, Final Sale)', 'Our Rome Boot in Navy is crafted with quality at the forefront. With our Rome Boot\'s versatile nature, they can be dressed up for formal event and in the same step, be ready for a relaxed night out. Not only are you going to love these boots, but everyone around you will too.', 279.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/313A2999-2048px.jpg?v=1762439557', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Toile', 'Plateforme', 'Lacets', 'homme', 'Botte versatile pour soirée ou soirée', 1, 75.8421, 4, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"indépendant\",\n      \"confiant\",\n      \"élégant\",\n      \"prévisible\"\n   ],\n   \"occasion_port\": \"sortie avec les amis, week-end en ville\"\n}', 0.0593289, -0.338489, 75.8705),
(204, '4348681584709', 3, 'https://taftclothing.com/products/the-hiro-boot-in-midnight', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Hiro Chelsea Boot in Midnight (Last Chance, Final Sale)', 'Our Hiro Boot in Midnight features a bold update from the classic Chelsea style giving you that perfect new jump into our boot collection. With their easy pull-on and pull-off feature, they are going to be a nice fit for all those special occasions. The upper material has been constructed from a boxcalf leather from Italy, and the cuff is constructed from a full grain leather with an embossed croc detailing. The interior is fully-lined with natural calfskin, and the sole unit is stacked leather with a rubber insert. They easily become an instant favorite having them made with Blake Construction.', 249.99, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/Taft_OnWhite_20191114_2601-min.jpg?v=1762439539', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Bois de cuir italien', 'Plateforme', 'Slip-on', 'homme', 'Botte en cuir italien avec détails en crocodile', 1, 77.3689, 4, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": \"35-50\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": {\n      \"ambitieux\": 0.8,\n      \"independent\": 0.7,\n      \"conformiste\": 0.2,\n      \"éclectique\": 0.9,\n      \"prévisible\": 0.4\n   },\n   \"occasion_port\": {\n      \"jour\": {\n         \"travail\": 0.6,\n         \"sortie avec des amis\": 0.3,\n         \"rendez-vous galant\": 0.1\n      },\n      \"soir\": {\n         \"sortie avec des amis\": 0.5,\n         \"rendez-vous galant\": 0.3,\n         \"événement professionnel\": 0.2\n      }\n   }\n}', -0.334248, -0.05253, 77.3803),
(205, '3924106903621', 3, 'https://taftclothing.com/products/the-dylan-boot-in-woven', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Dylan Jodhpur Boot in Woven (Last Chance, Final Sale)', 'Our Dylan boot in Woven, is a beautiful Jodhpur boot with a very sleek silhouette, ankle strap, and buckle. The leather it has been made out of is carefully hand-woven in Spain and burnished with heat and stain to create that stunning finishing look. Featuring its blake-stitched construction and durable material that will keep your shoes looking good for years. We then use our Bristol last, giving it that very slim, sleek, and minimal shape.', 300.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/Taft_OnWhite_20190526_1633-min.jpg?v=1762439520', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir italien', 'Plateforme', 'Slip-on', 'homme', 'Botte Jodhpur avec détails en cuir', 1, 74.7368, 4, '{\n  \"nom_persona\": \"Lola\",\n   \"age_cible\": \"28-45\",\n   \"style_vie\": \"Rustique Chic\",\n   \"traits_personnalite\": [\n      \"Indépendante\",\n      \"Ambitieuse\",\n      \"Avec un goût pour la mode éclectique\"\n   ],\n   \"occasion_port\": [\n      \"Sorties en ville\",\n      \"Week-ends en campagne\",\n      \"Événements de style\"\n   ]\n}', -0.334248, -0.05253, 74.7631),
(206, '2097411260485', 3, 'https://taftclothing.com/products/the-sneaker-in-stripes', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Sneaker in Stripes (Last Chance, Final Sale)', 'The Men\'s Sneaker in Stripes from TAFT is the most hyped release from the collection. The upper is made from a water-repellent acrylic sourced in Italy.', 135.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/Taft_OnWhite_20190315-031-min.jpg?v=1762439501', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Acrylique', 'Gomme', 'Slip-on', 'homme', 'Sneaker en acrylique', 1, 83.4211, 4, '{\n  \"nom_persona\": \"Alexandre \'Lex\' Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": [\n      \"Ambitieux\",\n      \"Innovant\",\n      \"Authentique\",\n      \"Passionné par la mode\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Événements sportifs\",\n      \"Réunions avec les amis\",\n      \"Défilés de mode\"\n   ]\n}', -0.46364, 0.511013, 83.3949),
(207, '154294485013', 3, 'https://taftclothing.com/products/the-rome-shoe-in-brown', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Rome Shoe in Brown', 'Meet the Rome Shoe, the shoe based on one of our most popular boots. This shoe is literally a work of art, requiring four different coats of paint and finish to obtain the rich finish in the leather.', 299.99, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/Taft_OnWhite_20171021_0013-min.jpg?v=1762439479', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Plateforme', 'Lacets', 'homme', 'Chaussure en cuir avec finition riche', 1, 74.7374, 4, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"appreciate la qualité\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"rendez-vous\",\n      \"week-end en ville\"\n   ]\n}', 0.173445, -0.194707, 74.7631),
(208, '9890860998', 3, 'https://taftclothing.com/products/the-beck-in-burnt-honey', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Beck Shoe in Burnt Honey', 'Meet the Beck in Burnt Honey. We have had countless requests to produce The Beck in a more traditional color and here it is. This full brogue wingtip was designed to take an everyday staple and turn it into something that will set you apart from the rest. The bold color is striking. The leather is cut by hand - rather than with a laser or machine. The sole is stacked leather with a rubber insert to provide grip, durability, and longevity. Like all Taft shoes, the Beck is fully leather-lined and constructed using Blake stitching.', 299.99, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/Taft_OnWhite_20170306-014-min_grande_8d57b1da-4116-4ccc-96f8-46481177c482.jpg?v=1762439470', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Plateforme', 'Lacets', 'homme', 'Chaussure en cuir avec détails en cuir', 1, 74.7374, 4, '{\n  \"nom_persona\": \"Luna Wilder\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Bohème Chic\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"originalité\": 9,\n      \"éclectisme\": 8,\n      \"passion\": 9,\n      \"authenticité\": 8\n   },\n   \"occasion_port\": {\n      \"jour\": {\n         \"travail\": 4,\n         \"sortie avec amis\": 6,\n         \"shopping\": 5\n      },\n      \"soir\": {\n         \"sortie romantique\": 7,\n         \"dîner en ville\": 6,\n         \"concert\": 5\n      }\n   }\n}', 0.173445, -0.194707, 74.7631),
(209, '8688759046', 3, 'https://taftclothing.com/products/the-troy-boot-in-black', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Troy Boot in Black (Last Chance, Final Sale)', 'Our Troy Boot in Black will become your new favorite go-to boots. With the perfect balance between a sleek yet rugged look and incredibly substantial suede with full leather lining, these boots will last you through all those nights to come. To give you some character, we have added gold details and highlights in the leather lining, eyelets, and the tips of the laces. Wearing these boots will definitely attract attention.', 147.50, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/mm_sized_wc_Taft_FW16_OnWhite_20160720_0056.jpg?v=1762439467', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Suede', 'Plateforme', 'Lacets', 'homme', 'Botte en suede avec détails en cuir', 1, 82.7632, 4, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"independance\": 9,\n      \"sensibilité\": 6,\n      \"authenticité\": 8\n   },\n   \"occasion_port\": {\n      \"journee_travail\": 6,\n      \"sortie_nuit\": 4,\n      \"week-end\": 8,\n      \"activités_au_parc\": 2\n   }\n}', -0.0895199, -0.410576, 82.7026),
(210, '3818822790', 3, 'https://taftclothing.com/products/the-jack-boot-in-black', 'Shoes', 'Sneakers', 'TAFT Clothing', 'The Jack in Black', 'The Jack in Black has quickly become a TAFT men\'s boot signature and the calfskin inner lining adds support and some structure to the 100% wool upper.', 349.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0468/9441/products/Taft_OnWhite_20161120-008-min.jpg?v=1762439464', '2026-03-24 16:33:22', '2026-03-24 16:33:22', '2026-04-16 20:28:53', 'Cuir', 'Plateforme', 'Lacets', 'homme', 'Botte en cuir avec détails en cuir', 1, 72.1579, 4, '{\n  \"nom_persona\": \"Jack\",\n   \"age_cible\": {\n      \"min\": 18,\n      \"max\": 35\n   },\n   \"style_vie\": {\n      \"activite\": \"sportive\",\n      \"loisirs\": [\"musique\", \"cinéma\", \"sorties\"],\n      \"mode_de_vie\": \"urbain\"\n   },\n   \"traits_personnalite\": {\n      \"confiance\": \"élevé\",\n      \"ouverture\": \"ouvert\",\n      \"sensibilité\": \"moyen\",\n      \"ambition\": \"forte\"\n   },\n   \"occasion_port\": {\n      \"journee_travail\": \"occasionnel\",\n      \"sorties_sociales\": \"fréquent\",\n      \"loisirs\": \"fréquent\",\n      \"activites_physiques\": \"fréquent\"\n   }\n}', 0.173445, -0.194707, 72.2005),
(211, '8356883857594', 4, 'https://www.beckettsimonon.com/products/gibson-suede-wingtips-mens', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Gibson Wingtips - Suede -  Men\'s', 'The modern wingtip derby in suede. Crafted from premium suede with a rich, velvety nap, this modern wingtip adds depth and understated sophistication to your wardrobe. Classic brogue detailing meets derby construction for a flexible, comfortable fit, while a chunky rubber lug sole delivers traction and durability. Double welting reinforces its bold profile, and a leather lining ensures breathable comfort. Naturally resilient and versatile, it’s built for smart-casual offices, fall layering, creative settings, and travel with refined, contemporary edge. This product is made from luxurious suede sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 239.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_chestnut_1_gibson_derbies_suede.jpg?v=1773874734', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Suede', 'Gomme', 'Lacets', 'homme', 'Derby en suede avec détails en cuir', 1, 77.9474, 1, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"35-45\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": {\n      \"ambitieux\": true,\n      \"conformiste\": false,\n      \"préoccupé par la qualité\": true,\n      \"attaché à l\'originalité\": true\n   },\n   \"occasion_port\": {\n      \"travail\": \"réunions d\'affaires, réceptions\",\n      \"sortie\": \"dîners, concerts\",\n      \"loisirs\": \"week-end en ville, voyages\"\n   }\n}', 0.121173, 0.00362955, 77.9539),
(212, '8356883398842', 4, 'https://www.beckettsimonon.com/products/gibson-wingtips-mens', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Gibson Wingtips - Men\'s', 'The bold brogued derby. The Gibson Wingtip Derbies are designed and crafted to elevate how you show up. Crafted from rich, hand-finished full-grain leather, they showcase timeless wingtip detailing and precise perforations. Derby construction ensures a comfortable, adaptable fit, while a chunky rubber lug sole delivers traction and durability. Double welting adds structure and edge, and the chunky rubber lug sole adds traction and durability, and leather lining ensures breathable comfort. Versatile, confident, and built to last. This product is made from full-grain calfskin leather sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 239.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_tan_1_gibson_derbies.jpg?v=1773873782', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Derby en cuir avec détails en cuir', 1, 77.9474, 1, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"35-50\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": {\n      \"ambitieux\": true,\n      \"independent\": true,\n      \"appreciate la qualité\": true,\n      \"préoccupé par l\'élégance\": true,\n      \"respectueux de la tradition\": true\n   },\n   \"occasion_port\": {\n      \"travail\": true,\n      \"réunions de affaires\": true,\n      \"sorties nocturnes\": true,\n      \"événements sociaux\": true,\n      \"voyages\": true\n   }\n}', 0.515126, 0.400522, 77.9539),
(213, '8338514706618', 4, 'https://www.beckettsimonon.com/products/maxwell-trainer-leather-suede-women', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Maxwell Trainer - Leather & Suede - Women\'s', 'A sneaker with depth. Slip into the Maxwell, a sneaker that feels as good as it looks. Smooth leather and soft suede come together in rich contrast, creating a silhouette with subtle depth that pairs perfectly with everything from denim to dresses. The well-balanced shape flatters and supports your foot while keeping things relaxed and modern. Underneath, a cushioned natural rubber sole moves with you, providing flexible, all-day comfort you can rely on. This product is made with full-grain calfskin leather and water-repellent suede sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 179.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_whiteblackwhite_4_maxwell_trainer_leather_suede_d3ff7de3-7da7-4ee7-803a-e6d3bdaf4078.jpg?v=1771539344', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'femme', 'Sneaker en cuir avec détails en cuir', 1, 81.1053, 3, '{\n  \"nom_persona\": \"Aurélie\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": {\n      \"ambitieux\": 8,\n      \"independent\": 9,\n      \"éclectique\": 7,\n      \"conscientieux\": 6,\n      \"passionné\": 8\n   },\n   \"occasion_port\": {\n      \"travail\": 6,\n      \"sortie nocturne\": 8,\n      \"rendez-vous amoureux\": 9,\n      \"activités de loisirs\": 7,\n      \"événements sociaux\": 8\n   }\n}', -0.296226, 0.575709, 81.0924),
(214, '8295838548154', 4, 'https://www.beckettsimonon.com/products/grayson-moc-toe-sneakers-mens', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Grayson Moc Toe Sneaker - Suede - Men\'s', 'The Elevated Moc-Toe Sneaker Crafted from premium water-repellent suede, the unlined Grayson Moc-Toe Sneaker delivers softness, breathability, and a naturally broken-in feel from day one. A hand-finished apron seam highlights the moc-toe design, while a lightweight, low-profile rubber sole provides flexible, all-day comfort. Streamlined proportions elevate it beyond casual wear, making it an effortless, versatile choice with denim, chinos, or polished everyday looks. This product is made from luxurious suede sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 179.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_taupegum_1_grayson_moc_toe_suede_59279cb1-c3bd-41f4-b00a-beea35149145.jpg?v=1773196551', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Suede', 'Gomme', 'Slip-on', 'homme', 'Sneaker en suede avec détails en cuir', 1, 81.1053, 3, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-45\",\n   \"style_vie\": {\n      \"activite\": \"urbaine\",\n      \"loisirs\": [\"musique\", \"cinéma\", \"lecture\"],\n      \"mode_de_vie\": \"urbain\"\n   },\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"originalité\": 7,\n      \"conformisme\": 4,\n      \"pulsion\": 6\n   },\n   \"occasion_port\": {\n      \"journee_travail\": true,\n      \"sortie_nuit\": true,\n      \"activite_physique\": false,\n      \"occasion_spéciale\": false\n   }\n}', -0.461517, 0.214444, 81.0924),
(215, '8269314097338', 4, 'https://www.beckettsimonon.com/products/silva-boots-mens', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Silva Boots - Men\'s', 'A Modern Take on a Classic Chelsea A timeless essential elevated by masterful craftsmanship, the Silva Boots in supple full-grain leather reinterpret the classic Chelsea with modern comfort and refined durability. Built on the Denver last, they follow the natural contours of the foot to reduce pressure points and create a balanced, supportive fit for all-day wear. Their handcrafted construction shines through in the precise stitching, thoughtfully placed panels, and expert finishing that reflect high-standard shoemaking, resulting in a refined, versatile boot made to last for years. This product is made from full-grain calfskin leather sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 299.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_tan_1_silva_boots_full-grain.jpg?v=1764888028', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Botte en cuir avec détails en cuir', 1, 74.7895, 3, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"25-45\",\n   \"style_vie\": \"urbain, actif, professionnel\",\n   \"traits_personnalite\": {\n      \"confiance\": \"élevée\",\n      \"ouverture\": \"moyenne\",\n      \"originalité\": \"élevée\",\n      \"prévisibilité\": \"moyenne\"\n   },\n   \"occasion_port\": {\n      \"jour\": \"travail, sorties\",\n      \"soir\": \"sorties, événements\",\n      \"week-end\": \"loisirs, activités\"\n   }\n}', -0.296226, 0.575709, 74.804),
(216, '8258772500666', 4, 'https://www.beckettsimonon.com/products/camden-derby-men-s', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Camden Derby - Men´s', 'Traditional craft meets modern character Command attention with the Camden Derbies, where timeless craftsmanship meets modern allure. The subtly detailed uppers, fashioned out of rich full-grain leather, stand out with a bold, chunky profile that exudes confident sophistication. Secured by the distinctive ArcLace drawstring system, you can count on them for effortless precision and contemporary flair. The double leather welt and rugged lug sole keep the Camden’s grounded and resilient. Being remarkably versatile, these derbies embody the perfect balance of heritage and forward-thinking design. This product is made from full-grain calfskin leather sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 239.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_black_1_camden_derbies_full_grain_d48fdc70-e278-4c2b-a337-20d99d158ef1.jpg?v=1773258060', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Derby en cuir avec détails en cuir', 1, 77.9474, 3, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain, actif, créatif\",\n   \"traits_personnalite\": [\n      \"independent\",\n      \"confiant\",\n      \"éclectique\",\n      \"passionné par la mode\"\n   ],\n   \"occasion_port\": [\n      \"rendez-vous professionnel\",\n      \"sortie avec des amis\",\n      \"événement social\",\n      \"jour de travail\"\n   ]\n}', -0.296226, 0.575709, 77.9539),
(217, '8258770272442', 4, 'https://www.beckettsimonon.com/products/astor-chelsea-boots-men-s', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Astor Chelsea Boot - Men´s', 'Command the ground you walk on The Astor Chelsea Boot transforms a classic profile into a bold statement. Handcrafted from supple yet sturdy full-grain leather that builds character with every wear, it’s defined by sleek elastic panels, reinforced pull tabs and commanding double leather welts. A grippy rugged rubber and EVA sole, breathable leather lining and cushioned footbed keep you moving in comfort. Built on the Denver last for a more natural fit, the Astor combines confidence, attitude and craftsmanship to keep you moving. This product is made from full-grain calfskin leather sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 269.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_brown_1_astor_chelsea_full_grain_017486a1-d5bd-4e3d-8e77-c49e8fe986bb.jpg?v=1763136008', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Botte en cuir avec détails en cuir', 1, 76.3684, 3, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"25-45\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": {\n      \"ambitieux\": true,\n      \"independent\": true,\n      \"appreciate la qualité\": true,\n      \"préoccupé par l\'apparence\": true\n   },\n   \"occasion_port\": {\n      \"travail\": true,\n      \"sorties nocturnes\": true,\n      \"week-end en ville\": true,\n      \"réunions professionnelles\": true\n   }\n}', -0.296226, 0.575709, 76.3826),
(218, '8224548159674', 4, 'https://www.beckettsimonon.com/products/warren-derby-men-s', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Warren Derby - Men´s', 'Timeless derby style with sneaker-level comfort. The Warren Derby, handcrafted from the finest full-grain leather, delivers timeless style with sneaker-level comfort. Its open-lacing design brings a sense of relaxed charm, and a lightweight EVA sole ensures effortless wear and grip. The smooth surface and expert stitching showcase artisanal craftsmanship, which is complemented by a Vachetta leather lining and a cushioned footbed. Subtle textures and layered details elevate the look, seamlessly blending tradition and modernity for a refined shoe that feels as good as it looks. This product is made from full-grain calfskin leather sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 219.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_black_1_warren_derbies_full_grain.jpg?v=1761069954', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Derby en cuir avec détails en cuir', 1, 79, 3, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": {\n      \"min\": 25,\n      \"max\": 45\n   },\n   \"style_vie\": {\n      \"professionnel\": true,\n      \"urbain\": true,\n      \"actif\": true\n   },\n   \"traits_personnalite\": {\n      \"confiant\": true,\n      \"independant\": true,\n      \"débrouillard\": true\n   },\n   \"occasion_port\": {\n      \"travail\": true,\n      \"sortie nocturne\": true,\n      \"réunion sociale\": true\n   }\n}', -0.296226, 0.575709, 78.9975),
(219, '8224545767610', 4, 'https://www.beckettsimonon.com/products/warren-derby-suede-men-s', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Warren Derby - Suede - Men´s', 'Step into all-day ease. The Warren Derby in premium suede provides exceptional comfort and lasting style. Designed for effortless versatility, its clean paneling and adjustable open-lacing ensure an easy fit. You can count on the supportive, lightweight, sculpted EVA sole for superior shock absorption and flexibility. Padded footbeds and supple Vachetta leather lining give additional support and comfort. Combined, these elements make the Warren Derby a refined essential for your everyday rotation. This product is made from luxurious suede sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 219.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_olive_1_warren_derbies_suede.jpg?v=1761068844', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Suede', 'Gomme', 'Slip-on', 'homme', 'Derby en suede avec détails en cuir', 1, 79, 3, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"35-45\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independent\",\n      \"appreciate la qualité\",\n      \"préoccupé par l\'élégance\"\n   ],\n   \"occasion_port\": \"rendez-vous professionnel, sorties nocturnes, week-ends en ville\"\n}', -0.461517, 0.214444, 78.9975),
(220, '8224525680826', 4, 'https://www.beckettsimonon.com/products/warren-derby-nubuck-men-s', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Warren Derby - Nubuck - Men´s', 'Modern design with exceptional comfort. The Warren Derby in plush nubuck leather is designed for remarkable comfort without compromising style. Its layered construction provides superior cushioning and impact absorption, making every step effortless. A lightweight EVA sole adds resilience, grip and flexibility, and the padded interior enhances support throughout the day. Subtle details, pristine paneling and open lacing ensure adaptability and ease of wear. Combining refined modernity with exceptional comfort, the Warren Derby is a timeless essential for the modern wardrobe. This product is made from supple and sultry nubuck leather sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 219.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_black_1_warren_derbies_nubuck.jpg?v=1761067938', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Nubuck', 'Gomme', 'Slip-on', 'homme', 'Derby en nubuck avec détails en cuir', 1, 79, 3, '{\n  \"nom_persona\": \"Ethan Thompson\",\n   \"age_cible\": \"28-42\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": [\n      \"confiant\",\n      \"independant\",\n      \"soigneux\"\n   ],\n   \"occasion_port\": \"rendez-vous professionnel, soirée en ville\"\n}', -0.300999, 0.145865, 78.9975),
(221, '8224522928314', 4, 'https://www.beckettsimonon.com/products/hudson-loafer-men-s', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Hudson Loafer - Men´s', 'A modern loafer with superior comfort. The Hudson Loafer redefines what comfort in a classic shoe can be. Crafted from luxurious full-grain leather, it combines timeless refinement with remarkable ease. The slightly elevated midsole enhances the shoe’s structure, and a cushioned, lightweight, resilient EVA sole delivers traction and shock absorption. With its layered construction and modern profile, the Hudson is more than a loafer, it’s a versatile essential designed for enduring comfort and built for life in motion. This product is made from full-grain calfskin leather sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 219.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_black_1_hudson_loafer_full_grain.jpg?v=1761066220', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Cuir', 'Plateforme', 'Scratch', 'homme', 'Loafer moderne avec confort supérieur', 1, 79, 4, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"35-45\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"ambitieux\",\n      \"independent\",\n      \"élégant\"\n   ],\n   \"occasion_port\": \"travail\", \n   \"autres_occasions\": [\n      \"rendez-vous\",\n      \"sorties avec les amis\",\n      \"week-end\"\n   ],\n   \"intérêts\": [\n      \"mode\",\n      \"musique\",\n      \"voyages\"\n   ],\n   \"niveau_revenu\": \"moyen-élevé\"\n}', -0.12992, -0.254733, 78.9975),
(222, '8224488685754', 4, 'https://www.beckettsimonon.com/products/hudson-loafer-suede-men-s', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Hudson Loafer - Suede - Men´s', 'Unmatched comfort with a classic profile. The Hudson Loafer blends timeless sophistication with effortless comfort. Handcrafted from premium suede with a refined nap, it offers understated elegance and a soft, flexible feel. A cushioned, multi-layer build and lightweight contrast EVA sole provide superior support, shock absorption and flexibility for all-day wear. Clean stitching, subtle detailing, and a classic penny strap balance heritage and modern style, creating a versatile loafer that looks refined and feels exceptionally comfortable from morning to night. This product is made from luxurious suede sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 219.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_brown_1_hudson_loafer_suede.jpg?v=1761065659', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Toile', 'Plateforme', 'Scratch', 'homme', 'Loafer classique avec confort inégalé', 1, 79, 4, '{\n  \"nom_persona\": \"Alexandre Dupont\",\n   \"age_cible\": 35,\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": {\n      \"ambitieux\": true,\n      \"sophistiqué\": true,\n      \"independent\": true,\n      \"appreciate la qualité\": true\n   },\n   \"occasion_port\": {\n      \"travail\": \"réunions de travail, réceptions\",\n      \"sortie\": \"dîners, concerts\",\n      \"loisirs\": \"week-end en ville, voyages\"\n   }\n}', -0.180928, -0.362493, 78.9975);
