(238, '8154093486266', 4, 'https://www.beckettsimonon.com/products/clement-derby-men-s-water-repellent-suede', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Clement Derby - Men’s  Water Repellent Suede', 'Subtle sophistication and lasting quality. Step into timeless style with the Clement Derby in velvety water-repellent suede, where traditional craftsmanship meets modern design. This elevated take on the traditional men\'s derby features a bold, grippy wave-patterned sole and double welt detailing to strike the perfect balance between heritage and contemporary styling. Handcrafted for versatility and sustainability, the Clement brings a sense of effortless polish to any casual setting. This product is made from luxurious suede sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 239.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_brown_1_clement_derbies_suede.jpg?v=1755802757', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'homme', 'Derby élégant et résistant', 1, 77.9474, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"28-45\",\n   \"style_vie\": {\n      \"activite\": \"urbain\",\n      \"loisirs\": [\"musique\", \"cinéma\", \"voyages\"],\n      \"mode_de_vie\": \"actif\"\n   },\n   \"traits_personnalite\": {\n      \"confiance\": \"élevée\",\n      \"independance\": \"forte\",\n      \"sensibilite\": \"moyenne\"\n   },\n   \"occasion_port\": {\n      \"occasion\": \"quotidien\",\n      \"evenement\": \"soirée\",\n      \"activite\": \"sortie\"\n   }\n}', 0.303358, 0.110112, 77.9539),
(239, '8154064847034', 4, 'https://www.beckettsimonon.com/products/fuentes-loafer-men-s-water-repellent-suede', 'Shoes', 'Sneakers', 'Beckett Simonon', 'Fuentes Loafer - Men’s Water-Repellent Suede', 'Easy to wear, impossible to ignore. Step into timeless style with the Fuentes Loafers in lush water-repellent suede. A bold twist on the classic penny loafer, they’re expertly handcrafted to age beautifully with a rich, personalized patina. The lightweight dual-density EVA lug sole offers cushioned comfort and strong traction for life on the go. Double welt detailing adds character and a refined edge. Whether you\'re dressing down or elevating casual looks, the Fuentes Loafers bring effortless sophistication and versatility to any outfit. This product is made from robust pull-up leather sourced from a Gold-Rated tannery based in Arzignano, Italy. Being the highest level of recognition awarded by the Leather Working Group, a Gold rating signifies the leather manufacturer meets the most stringent criteria and demonstrates a strong commitment to mitigating its environmental impact.', 239.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0175/8496/files/color_brown_1_fuentes_loafers_suede.jpg?v=1762322038', '2026-03-24 16:34:33', '2026-03-24 16:34:33', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'homme', 'Loafer élégant et résistant', 1, 77.9474, 1, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"35-50\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"independant\",\n      \"ambitieux\",\n      \"décontracté\",\n      \"éclectique\"\n   ],\n   \"occasion_port\": [\n      \"rendez-vous professionnels\",\n      \"sorties nocturnes\",\n      \"week-ends en ville\",\n      \"voyages d\'affaires\"\n   ]\n}', 0.303358, 0.110112, 77.9539),
