(316, '9057348026701', 15, 'https://www.fillingpieces.com/products/light-plain-court-beige', 'Shoes', 'Sneakers', 'Filling Pieces', 'Court Suede Beige', 'A classic tennis shoe silhouette that\'s comfortable enough to be worn every day. Soft, flexible leather suede uppers with an absorbent mesh lining are paired with lightweight yet cushioned sole.', 200.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133134145-1_9bf40423-24d4-4d47-ae4a-f8d572769640.jpg?v=1749652575', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Toile', 'Gomme', 'Lacets', 'unisexe', 'Sneakers en toile', 1, 80, 1, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": [\n      \"Indépendante\",\n      \"Créative\",\n      \"Élégante\",\n      \"Consciente de l\'environnement\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Réunions avec des amis\",\n      \"Journées de shopping\",\n      \"Événements de mode\"\n   ]\n}', 0.303358, 0.110112, 79.995),
