(319, '10422820962637', 15, 'https://www.fillingpieces.com/products/lux-loafer-polido-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Lux Loafer Polido Black', 'The Lux Loafer Polido Black offers a minimalist take on our classic loafer design. Built on a rubber and microfiber sole, it’s made from premium polido leather and unlined for durability and breathability. With subtle improvements to further enhance the comfort, the heel is padded with soft foam and finished in suede microfiber and the insole is also provided with cushioning foam beneath a smooth leather lining. The clean polido penny loafer bridge makes this a versatile and elegant choice for any wardrobe.', 320.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/LuxLoaferPolidoBlack-2.jpg?v=1773223610', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Loafer en cuir', 1, 73.6842, 1, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"habitudes\": \"urbaine\",\n      \"loisirs\": \"musique, cinéma, lecture\",\n      \"mode_de_vie\": \"actif, créatif\"\n   },\n   \"traits_personnalite\": {\n      \"values\": \"qualité, simplicité, authenticité\",\n      \"attitudes\": \"éclectique, curieux, ouvert\"\n   },\n   \"occasion_port\": {\n      \"journee_travail\": \"réunion de travail, déjeuner en ville\",\n      \"soiree\": \"sortie avec des amis, événement culturel\",\n      \"weekend\": \"promenade en ville, brunch\"\n   }\n}', 0.515126, 0.400522, 73.7183),
(320, '8694813950285', 15, 'https://www.fillingpieces.com/products/loafer-gowtu-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Gowtu Black', 'Immerse yourself in luxury with the Loafer Gowtu Black, where premium Nappa piping intertwines with a plush Polido leather upper. Inspired by the profound \'Matten-Klopper\' ring, this loafer embodies a journey of renewal and the casting off of negativity. Crafted with precision from Cow Polido leather and adorned with a striking Poliéster patch, it encapsulates a perfect harmony of heritage and contemporary style.', 390.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/Loafer_Gowtu_Black-1.jpg?v=1749629191', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Loafer en cuir', 1, 70, 1, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confident\": true,\n      \"independant\": true,\n      \"éclectique\": true,\n      \"appreciate la qualité\": true,\n      \"conscient de l\'environnement\": true\n   },\n   \"occasion_port\": {\n      \"jour de travail\": true,\n      \"sorties nocturnes\": true,\n      \"week-end\": true,\n      \"vacances\": false\n   }\n}', 0.515126, 0.400522, 70.1116),
(321, '10080537641293', 15, 'https://www.fillingpieces.com/products/loafer-rugby-degrade-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Rugby Degrade Black', 'The iconic Patch Loafer is reimagined with a modern, technical edge, bridging classic footwear with contemporary graphic art. Crafted from high-shine polido leather, the shoe features a unique \'Rugby\' patch whose degrade pattern visualizes the flow of digital soundwaves. This statement piece merges formal elegance with a disruptive, artistic spirit.', 350.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133413295-2_1.jpg?v=1754996390', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Polido leather', 'Plateforme', 'Scratch', 'homme', 'Loafer Rugby Degrade Black', 1, 72.1053, 4, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"originalité\": 9,\n      \"éclectisme\": 7,\n      \"sensibilité\": 6,\n      \"influenceur\": 5\n   },\n   \"occasion_port\": {\n      \"jour\": \"sortie avec des amis\",\n      \"soir\": \"dîner en ville\",\n      \"weekend\": \"week-end en ville ou à la campagne\"\n   }\n}', -0.281854, -0.353208, 72.1679),
(322, '9786272416077', 15, 'https://www.fillingpieces.com/products/tiebreak-core-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Tiebreak Core Black', 'The Tiebreak Core Black combines luxury with a vintage tennis aesthetic. This premium sneaker is crafted from smooth nappa leather and features hand-stitched detailing and a gold embossed logo. With a mesh tongue for breathability and comfort, it’s fully lined with cow leather, ensuring durability. Built on the Riviera rubber cupsole, it features the iconic FP Gowtu knot monogram for added style.', 240.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133315315-1_1_1_700142e6-1a75-4cb7-9eed-1cbf2dd40537.jpg?v=1744370346', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Smooth nappa leather', 'Gomme', 'Lacets', 'homme', 'Tiebreak Core Black', 1, 77.8947, 4, '{\n  \"nom_persona\": \"Liam\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"independent\",\n      \"confiant\",\n      \"élégant\",\n      \"passionné par la mode\"\n   ],\n   \"occasion_port\": [\n      \"sortie en ville\",\n      \"rendez-vous\",\n      \"soirée\",\n      \"événement important\"\n   ]\n}', -0.0433643, -0.0943398, 77.9058),
(323, '9786269729101', 15, 'https://www.fillingpieces.com/products/mondo-viera-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Viera Black', 'The Mondo Viera Black features a wider, rounder toe shape, providing extra comfort without sacrificing style. Crafted from smooth nappa with contrasting hairy suede details, this shoe has added depth and is built on our new Riviera rubber cupsole. The FP Gowtu knot pattern as a monogram on the bottom sole makes this pair both classic and distinctive.', 220.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133316053-1_1_3631aae1-94cb-4d0f-9f99-f0044f583dc2.jpg?v=1744706721', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Smooth nappa with contrasting hairy suede details', 'Gomme', 'Lacets', 'homme', 'Mondo Viera Black', 1, 78.9474, 4, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": {\n      \"confident\": true,\n      \"independant\": true,\n      \"éclectique\": true,\n      \"appreciate la qualité\": true,\n      \"sensibilité pour l\'environnement\": true\n   },\n   \"occasion_port\": {\n      \"jour de travail\": {\n         \"matin\": \"à la réunion\",\n         \"après-midi\": \"à la réunion ou au déjeuner\"\n      },\n      \"sortie nocturne\": {\n         \"soirée\": \"dîner ou boîte de nuit\",\n         \"week-end\": \"sortie avec des amis\"\n      },\n      \"loisirs\": {\n         \"week-end\": \"sortie avec des amis ou en solo\",\n         \"vacances\": \"voyage ou détente\"\n      }\n   }\n}', -0.0675574, -0.145151, 78.9466),
(324, '10330224623949', 15, 'https://www.fillingpieces.com/products/loafer-solid-raffia-natural', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Solid Raffia Natural', 'The Loafer Solid Raffia is an outspoken hero piece from the SS26 collection, showcasing innovative, artisanal materials. This loafer is defined by its custom-engineered raffia upper, developed in collaboration with specialized ateliers. The natural texture is juxtaposed against smooth Polido leather accents  and elevated by our custom hand-shake hardware. This piece seamlessly merges high-end craft with a classic silhouette.', 350.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133596349-5.jpg?v=1771412992', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Custom-engineered raffia upper', 'Plateforme', 'Scratch', 'homme', 'Loafer Solid Raffia Natural', 1, 72.1053, 4, '{\n  \"nom_persona\": \"Léo\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"loisirs\": [\"musique\", \"cinéma\", \"voyages\"],\n      \"activités\": [\"sport\", \"lecture\"],\n      \"intérêts\": [\"mode\", \"art\", \"culture\"]\n   },\n   \"traits_personnalite\": {\n      \"values\": [\"authenticité\", \"originalité\", \"qualité\"],\n      \"priorités\": [\"confort\", \"élegance\", \"durabilité\"],\n      \"attitudes\": [\"écologique\", \"responsable\"]\n   },\n   \"occasion_port\": {\n      \"jour_né\": \"week-end\",\n      \"soirée\": \"dîner avec des amis\",\n      \"activités\": [\"sortie en ville\", \"événement culturel\"]\n   }\n}', -0.186937, -0.280871, 72.1679),
(325, '10330224591181', 15, 'https://www.fillingpieces.com/products/loafer-panier-tea', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Panier Tea', 'This is a testament to artisanal heritage. The Loafer Panier is a true hero piece, defined by its custom-designed, ratan-engineered upper developed in collaboration with specialized Spanish ateliers. The intricate, woven upper is crafted on a microfiber base with special embroidery degrade thread. Finished in Portugal, this loafer in Tea is elevated with Polido leather trim and our custom hand-shake hardware.', 390.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133779964-5.jpg?v=1771413015', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Custom-designed, ratan-engineered upper', 'Plateforme', 'Scratch', 'homme', 'Loafer Panier Tea', 1, 70, 4, '{\n  \"nom_persona\": \"Léo\",\n   \"age_cible\": {\n      \"min\": 25,\n      \"max\": 45\n   },\n   \"style_vie\": {\n      \"urban\": 0.8,\n      \"urbain\": 0.7,\n      \"bohème\": 0.3,\n      \"classique\": 0.2\n   },\n   \"traits_personnalite\": {\n      \"independant\": 0.9,\n      \"confiant\": 0.8,\n      \"éclectique\": 0.7,\n      \"conscientieux\": 0.6\n   },\n   \"occasion_port\": {\n      \"journée_travail\": 0.6,\n      \"sortie_nuit\": 0.4,\n      \"week-end\": 0.8,\n      \"événement_spécial\": 0.2\n   }\n}', -0.178152, -0.266777, 70.1116),
(326, '10330224525645', 15, 'https://www.fillingpieces.com/products/loafer-panier-beige', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Panier Beige', 'This is a testament to artisanal heritage. The Loafer Panier is a true hero piece, defined by its custom-designed, ratan-engineered upper developed in collaboration with specialized Spanish ateliers. The intricate, woven upper is crafted on a microfiber base with special embroidery degrade thread. Finished in Portugal, this Beige loafer is elevated with Polido leather trim and our custom hand-shake hardware.', 390.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133596349-6.jpg?v=1771413024', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Custom-designed, ratan-engineered upper', 'Plateforme', 'Scratch', 'homme', 'Loafer Panier Beige', 1, 70, 4, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain-chic\",\n   \"traits_personnalite\": {\n      \"confident\": 8,\n      \"independant\": 9,\n      \"éclectique\": 7,\n      \"conscientieux\": 6,\n      \"décontracté\": 5\n   },\n   \"occasion_port\": {\n      \"jour\": {\n         \"travail\": 4,\n         \"sortie avec amis\": 3,\n         \"shopping\": 2\n      },\n      \"soir\": {\n         \"sortie romantique\": 5,\n         \"dîner avec amis\": 4,\n         \"événement social\": 3\n      }\n   }\n}', -0.178152, -0.266777, 70.1116),
(327, '10330223804749', 15, 'https://www.fillingpieces.com/products/prism-peak-all-beige', 'Shoes', 'Sneakers', 'Filling Pieces', 'Prism Peak All Beige', 'Inspired by the dynamic fusion of running and skate culture, the Prism is a fresh take on a classic silhouette, resurrected from our archive of never-released prototypes. This sneaker showcases smart paneling with a blend of 3D mesh, supple nappa leather, and soft suede. The shoe is finished with vibrant, triple-colored rope laces and a plush footbed and lining, creating a harmonious and comfortable design.', 250.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/Prism_Peak_All_Beige_4.jpg?v=1767707080', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', '3D mesh, supple nappa leather, and soft suede', 'Gomme', 'Scratch', 'homme', 'Prism Peak All Beige', 1, 77.3684, 4, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain-chic\",\n   \"traits_personnalite\": {\n      \"conformiste\": 0.2,\n      \"innovant\": 0.8,\n      \"éclectique\": 0.5,\n      \"prévisible\": 0.3,\n      \"décisif\": 0.9\n   },\n   \"occasion_port\": {\n      \"jour-né\": 0.1,\n      \"sortie-restaurant\": 0.2,\n      \"événement-sportif\": 0.3,\n      \"rendez-vous-amical\": 0.4\n   }\n}', -0.199154, -0.195004, 77.3803),
(328, '10330224918861', 15, 'https://www.fillingpieces.com/products/hybrid-loafer-quilted-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Hybrid Loafer Quilted Black', 'A fan favorite from our 2020 collection, the Hybrid Loafer Quilted Black returns with its distinctive blend of classic and athletic design. This hybrid features the details and lines of our known loafers, enhanced by a textural, quilted black upper. This traditional upper sits atop a custom, comfortable EVA sole, providing a contemporary, lightweight base. It\'s the perfect convergence of bold texture and athletic wearability.', 350.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/HybridLoaferQuiltedBlack-2.jpg?v=1770026338', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Textural, quilted black upper', 'EVA', 'Scratch', 'homme', 'Hybrid Loafer Quilted Black', 1, 72.1053, 4, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"vêtements\": \"élégant\",\n      \"chaussures\": \"comfortable\",\n      \"accessoires\": \"minimaliste\"\n   },\n   \"traits_personnalite\": {\n      \"influences\": \"mode streetwear\",\n      \"priorités\": \"qualité\",\n      \"hobbies\": \"musique, voyage\"\n   },\n   \"occasion_port\": {\n      \"jour\": \"tous les jours\",\n      \"soirée\": \"occasionnelle\",\n      \"événement\": \"événements de mode\"\n   }\n}', -0.161624, -0.250441, 72.1679),
(329, '8694816538957', 15, 'https://www.fillingpieces.com/products/riviera-low-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Riviera Low Black', 'Elevate your summer style with our Riviera, a canvas sneaker that seamlessly blends relaxed comfort with timeless luxury. The shoe features a refined Nappa leather toe box and a sleek flat sole for a sophisticated touch. The Riviera is a perfect fusion of breathable fabric and premium leather, making it an ideal choice for both comfort and style.', 220.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133497240_82fe2e68-6096-4318-bf25-4d437a12a2cb.jpg?v=1747382872', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Nappa leather and canvas', 'Plateforme', 'Scratch', 'homme', 'Riviera Low Black', 1, 78.9474, 4, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain chic\",\n   \"traits_personnalite\": {\n      \"independant\": true,\n      \"éclectique\": true,\n      \"appreciate la qualité\": true,\n      \"conscient de l\'environnement\": true,\n      \"aimant l\'expérimentation\": true\n   },\n   \"occasion_port\": {\n      \"jour de travail\": true,\n      \"sortie le soir\": true,\n      \"week-end en ville\": true,\n      \"vacances ensoleillées\": true\n   }\n}', -0.261863, -0.332171, 78.9466),
(330, '10330224984397', 15, 'https://www.fillingpieces.com/products/hybrid-loafer-polido-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Hybrid Loafer Polido Black', 'The Hybrid Loafer Polido Black is a popular style brought back from our 2020 collection. This shoe seamlessly fuses classic loafer lines with an athletic design language. Crafted from sleek, high-shine Polido leather, the upper maintains a formal aesthetic, while the comfortable, custom EVA sole introduces a modern, lightweight foundation built for everyday mobility. This loafer truly embodies the hybrid blend of sophistication and sport.', 350.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-Hybrid_Loafer_Polido_Black-2.jpg?v=1770028271', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Sleek, high-shine Polido leather', 'EVA', 'Scratch', 'homme', 'Hybrid Loafer Polido Black', 1, 72.1053, 4, '{\n  \"nom_persona\": \"Léo Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"activité\": \"urbaine\",\n      \"loisirs\": [\"musique\", \"cinéma\", \"lecture\"],\n      \"mode_de_vie\": \"urbain\"\n   },\n   \"traits_personnalite\": {\n      \"confiance\": \"élevée\",\n      \"ouverture_d\'esprit\": \"élevée\",\n      \"éclectisme\": \"élevé\"\n   },\n   \"occasion_port\": {\n      \"jour\": \"tous les jours\",\n      \"soirée\": \"occasionnellement\",\n      \"événementiel\": \"rarement\"\n   }\n}', -0.227851, -0.288312, 72.1679),
(331, '10330224820557', 15, 'https://www.fillingpieces.com/products/bulky-derby-pepper-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Bulky Derby Pepper Black', 'The Bulky Derby Pepper Black introduces a fresh, confident silhouette to our collection. This style features a more bulky and rounder shape, built atop a new, substantial sole that updates the classic derby aesthetic. Crafted from fine Polido leather, the shoe maintains a polished finish. The black version is distinguished by custom artistry: a detailed pepper artwork is embroidered directly onto the toe-box, providing a unique and subtle narrative detail. Designed for comfort, the derby is built on a lightweight EVA sole and lined with a soft, breathable mesh lining for all-day ease.', 300.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26BulkyDerbyPepperBlack-2.jpg?v=1769510048', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Fine Polido leather', 'Plateforme', 'Scratch', 'homme', 'Bulky Derby Pepper Black', 1, 74.7368, 4, '{\n  \"nom_persona\": \"Kai Rensen\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": [\n      \"Ambitieux\",\n      \"Conformiste\",\n      \"Aimé la technologie\",\n      \"Apprécie la mode\",\n      \"A une esthétique soignée\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Réunions avec des amis\",\n      \"Événements de mode\",\n      \"Déplacements urbains\",\n      \"Photos sur les réseaux sociaux\"\n   ]\n}', -0.252472, -0.323185, 74.7631),
(332, '10330222395725', 15, 'https://www.fillingpieces.com/products/mondo-stack-suede-light-grey', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Stack Suede Light Grey', 'The Mondo Stack in Light Grey is our classic Mondo silhouette with elevated construction and detail. Crafted from layered premium nappa leather, the design gains superior structure and depth. A precisely stitched panel replaces the traditional piping, emphasizing the clean lines of the shoe. The upper is finished with a contrasting heel tab for a sharp, sophisticated visual anchor.', 220.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-Mondo_Stack_Suede_Light_Grey-1.jpg?v=1764774742', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Layered premium nappa leather', 'Gomme', 'Scratch', 'homme', 'Mondo Stack Suede Light Grey', 1, 78.9474, 4, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"indépendante\",\n      \"créative\",\n      \"éclectique\",\n      \"appreciative de la qualité\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"rendez-vous amicaux\",\n      \"événements culturels\",\n      \"voyages\"\n   ]\n}', -0.165577, -0.134703, 78.9466),
(333, '10422820667725', 15, 'https://www.fillingpieces.com/products/loafer-polido-minimum-matte-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Polido Minimum Matte Black', 'The Loafer Polido Minimum Matte Black offers a minimalist take on our classic loafer design. Built on a pre-fab leather and rubber sole, it’s made from premium polido leather and lined with leather for durability and comfort. The clean polido penny-loafer bridge makes this a versatile and elegant choice for any wardrobe. Premium quality also includes comfort. With subtle improvements to further enhance the comfort, the heel is padded with soft foam and finished in suede microfiber and the insole is also provided with cushioning foam beneath a smooth leather lining.', 320.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133051572-1.jpg?v=1768220970', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Polido leather and rubber', 'Plateforme', 'Scratch', 'homme', 'Loafer Polido Minimum Matte Black', 1, 73.6842, 4, '{\n  \"nom_persona\": \"Alexandre\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"loisirs\": [\"musique\", \"cinéma\", \"voyages\"],\n      \"activités\": [\"sport\", \"lecture\", \"cuisine\"],\n      \"intérêts\": [\"mode\", \"art\", \"photographie\"]\n   },\n   \"traits_personnalite\": {\n      \"ambitieux\": true,\n      \"créatif\": true,\n      \"independent\": true,\n      \"sophistiqué\": true\n   },\n   \"occasion_port\": {\n      \"journée_travail\": true,\n      \"sortie_nuit\": true,\n      \"week-end\": true,\n      \"événement_spécial\": true\n   }\n}', -0.299168, -0.337226, 73.7183),
(334, '10330223214925', 15, 'https://www.fillingpieces.com/products/cruiser-weave-beige', 'Shoes', 'Sneakers', 'Filling Pieces', 'Cruiser Weave Beige', 'The Cruiser Weave Beige offers a refined, textural take on our classic silhouette. Expertly crafted to blend premium quality with intentional design, this shoe maintains sophistication without being outspoken. The upper is defined by a dynamic material mix, primarily featuring woven Organic Cotton Fabric combined with soft hairy suede and durable rubberized leather. Presented in the versatile Beige colorway, this sneaker delivers essential, high-end style that easily integrates into any modern wardrobe.', 250.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133873686-1.jpg?v=1768219427', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Woven Organic Cotton Fabric, soft hairy suede, and durable rubberized leather', 'Plateforme', 'Scratch', 'homme', 'Cruiser Weave Beige', 1, 77.3684, 4, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"indépendant\",\n      \"éclectique\",\n      \"appreciate la qualité\",\n      \"préoccupé par l\'environnement\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"week-ends en ville\",\n      \"rendez-vous amicaux\",\n      \"événements de mode\"\n   ]\n}', -0.252952, -0.330819, 77.3803),
(335, '10330221969741', 15, 'https://www.fillingpieces.com/products/mondo-suede-tea', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Suede Tea', 'The Mondo Suede Tea derives true versatility from a minimalist silhouette and subtle detailing. This leather sneakers unassuming design is timeless, and gets updated for new seasons in contemporary fashion. This particular model puts an emphasis on organic, traceable materials and features a suede leather upper with mudguards, heel tab and subtle branding.', 190.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133046677-1.jpg?v=1768219330', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Suede leather', 'Gomme', 'Scratch', 'homme', 'Mondo Suede Tea', 1, 80.5263, 4, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": {\n      \"mode\": \"éclectique\",\n      \"influences\": [\"streetwear\", \"boho chic\"],\n      \"priorités\": [\"qualité\", \"originalité\"]\n   },\n   \"traits_personnalite\": {\n      \"ouverture\": \"ouvert\",\n      \"curiosité\": \"élevée\",\n      \"independance\": \"forte\"\n   },\n   \"occasion_port\": {\n      \"jour\": {\n         \"travail\": \"occasionnel\",\n         \"sortie\": \"fréquente\",\n         \"loisirs\": \"fréquente\"\n      },\n      \"soir\": {\n         \"sortie\": \"fréquente\",\n         \"dîner\": \"occasionnel\",\n         \"événement\": \"rare\"\n      }\n   }\n}', -0.235795, -0.164471, 80.504),
(336, '10330224755021', 15, 'https://www.fillingpieces.com/products/bulky-derby-brown', 'Shoes', 'Sneakers', 'Filling Pieces', 'Bulky Derby Brown', 'A more robust and rounded derby, the Bulky Derby Brown stands on a new custom-designed sole. This modern silhouette is crafted from fine Polido black leather, and features a subtle mini gowtu embossed knot on the toe box for a touch of refined detail. The shoe is built for comfort with a lightweight EVA sole and a soft, breathable mesh lining, creating a harmonious blend of style and wearability.', 280.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-BulkyDerbyBrown-1.jpg?v=1764758860', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Fine Polido leather', 'EVA', 'Scratch', 'homme', 'Bulky Derby Brown', 1, 75.7895, 4, '{\n  \"nom_persona\": \"Liam\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": [\n      \"Ambitieux\",\n      \"Tendre\",\n      \"Authentique\",\n      \"Conscientieux\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Réunions avec des amis\",\n      \"Événements de mode\",\n      \"Journées de shopping\"\n   ]\n}', -0.214229, -0.276262, 75.8073),
(337, '4409796788291', 15, 'https://www.fillingpieces.com/products/mondo-2-0-ripple-nappa-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo 2.0 Ripple Nappa White', 'Our most minimalistic sneaker. Silky-smooth nappa uppers sit upon our sleek Fundamental Ripple sole. A timeless classic updated with a contemporary heel tab and heatseam signature logo.', 200.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133199335-1_f7fe664c-1f6a-48ea-8ce1-9b64acefe1ec.jpg?v=1747382809', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Silky-smooth nappa upper', 'Gomme', 'Scratch', 'homme', 'Mondo 2.0 Ripple Nappa White', 1, 80, 4, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain chic\",\n   \"traits_personnalite\": [\n      \"independante\",\n      \"tendance\",\n      \"éclectique\",\n      \"appreciative de la qualité\",\n      \"consciente de l\'environnement\"\n   ],\n   \"occasion_port\": [\n      \"sortie avec des amis\",\n      \"rendez-vous galant\",\n      \"événement de mode\",\n      \"jour de travail\",\n      \"week-end en ville\"\n   ]\n}', -0.11269, -0.113752, 79.995),
(338, '6622005297219', 15, 'https://www.fillingpieces.com/products/loafer-polido-white-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Polido White / Black', 'Adding premium Nappa piping to a luxurious Polido leather upper, the Loafer Polido reimagines the classic loafer silhouette to a true FP statement piece. It features a gold-coloured handshake bridge and Filling Pieces branding on the heel while standing on a smooth leather outsole for a contemporary look.', 350.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/39D15A54-4EC0-4B10-BC21-715AEF8C657D_3.jpg?v=1748332033', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Polido leather and Nappa piping', 'Gomme', 'Scratch', 'homme', 'Loafer Polido White / Black', 1, 72.1053, 4, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"independance\": 9,\n      \"sensibilité\": 6,\n      \"éclectisme\": 8,\n      \"authenticité\": 9\n   },\n   \"occasion_port\": {\n      \"journee_travail\": \"occasionnel\",\n      \"sortie_nuit\": \"frequent\",\n      \"weekend\": \"frequent\",\n      \"activites_urbaines\": \"frequent\",\n      \"événements_sociaux\": \"occasionnel\"\n   }\n}', -0.173875, -0.154309, 72.1679);
