(339, '6612413055043', 15, 'https://www.fillingpieces.com/products/loafer-polido-all-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Polido All Black', 'Adding premium Nappa piping to a luxurious Polido leather upper, the Loafer Polido reimagines the classic loafer silhouette to a true FP statement piece. It features a gold-coloured handshake bridge and Filling Pieces branding on the heel while standing on a smooth leather outsole for a contemporary look.', 350.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133753223-1.jpg?v=1748332031', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Polido leather', 'Gomme', 'Scratch', 'homme', 'Loafer Polido All Black', 1, 72.1053, 4, '{\n  \"nom_persona\": \"Léo Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"ambitieux\": 8,\n      \"independent\": 9,\n      \"éclectique\": 7,\n      \"conscientieux\": 6,\n      \"décontracté\": 8\n   },\n   \"occasion_port\": {\n      \"journée\": {\n         \"travail\": 8,\n         \"sortie avec amis\": 9,\n         \"shopping\": 7\n      },\n      \"soirée\": {\n         \"dîner en ville\": 6,\n         \"sortie en boîte\": 5,\n         \"événement culturel\": 8\n      }\n   }\n}', -0.174581, -0.117926, 72.1679),
(340, '6572639846467', 15, 'https://www.fillingpieces.com/products/mondo-squash-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Squash White', 'The timeless Mondo Squash features a premium Nappa leather upper complemented by suede mudguards, all resting on the sleek Fundament Ripple outsole. This version boasts a distinctive branded heel patch and is completed with tonal waxed cotton laces featuring contrasting lacetips.', 200.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/AW21_Drop01_46733331901-1_328c0013-be46-42a8-b798-72ba2c57846f.jpg?v=1747382815', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Premium Nappa leather and suede', 'Gomme', 'Scratch', 'homme', 'Mondo Squash White', 1, 80, 4, '{\n  \"nom_persona\": \"Léa\",\n   \"age_cible\": {\n      \"min\": 25,\n      \"max\": 40\n   },\n   \"style_vie\": {\n      \"urban\": 0.8,\n      \"bohème\": 0.1,\n      \"chic\": 0.1\n   },\n   \"traits_personnalite\": {\n      \"independante\": 0.9,\n      \"confiante\": 0.8,\n      \"éclectique\": 0.9\n   },\n   \"occasion_port\": {\n      \"jour de travail\": 0.4,\n      \"sortie avec des amis\": 0.3,\n      \"événement social\": 0.2,\n      \"loisirs\": 0.1\n   }\n}', -0.201627, -0.194181, 79.995),
(341, '10080537379149', 15, 'https://www.fillingpieces.com/products/loafer-reed-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Reed Black', 'The classic loafer is transformed with an innovative, micro-quilted vegan leather, creating a detailed diamond pattern for a contemporary textural statement. Accented with high-shine polido leather details, the design can be personalized with a separate, removable Gowtu Pin for a signature touch. Built on our custom loafer sole, this black iteration merges sustainable innovation with timeless sophistication.', 300.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/Loafer-Reed02_77961858-9b0a-44b1-8e61-fc67fe3280b0.jpg?v=1759414994', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Vegan leather', 'Rubber sole', 'Slip-on', 'homme', 'Loafer avec cuir vegan et détails en polido', 1, 74.7368, 0, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"indépendant\",\n      \"créatif\",\n      \"éclectique\",\n      \"appreciate la qualité\",\n      \"préoccupé par l\'environnement\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"rendez-vous\",\n      \"week-end en ville\",\n      \"voyages\",\n      \"journées de travail\"\n   ]\n}', -0.450003, -0.133128, 74.7631),
(342, '10080567820621', 15, 'https://www.fillingpieces.com/products/riviera-low-beige', 'Shoes', 'Sneakers', 'Filling Pieces', 'Riviera Low Beige', 'The Riviera Low Beige is a canvas sneaker that balances ease and sophistication. It features a refined Nappa leather toe box and a sleek flat sole. Lightweight and breathable, the mix of fabric and leather makes it a comfortable yet polished choice.', 220.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133594659-1.jpg?v=1749572022', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir et toile', 'Plateforme', 'Slip-on', 'homme', 'Sneaker en toile et cuir', 1, 78.9474, 4, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"28-35\",\n   \"style_vie\": \"urbain-chic\",\n   \"traits_personnalite\": {\n      \"conformiste\": 0.2,\n      \"innovant\": 0.8,\n      \"éclectique\": 0.5,\n      \"prévisible\": 0.3,\n      \"excentrique\": 0.2\n   },\n   \"occasion_port\": {\n      \"journee_travail\": 0.4,\n      \"sortie_nuit\": 0.3,\n      \"week-end\": 0.3,\n      \"vacances\": 0.1,\n      \"événementiel\": 0.1\n   }\n}', -0.323129, -0.0764608, 78.9466),
(343, '10080567755085', 15, 'https://www.fillingpieces.com/products/riviera-low-dark-grey', 'Shoes', 'Sneakers', 'Filling Pieces', 'Riviera Low Dark Grey', 'The Riviera Low Dark Grey is a canvas sneaker that balances ease and sophistication. It features a refined Nappa leather toe box and a sleek flat sole. Lightweight and breathable, the mix of fabric and leather makes it a comfortable yet polished choice.', 220.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133598138-1.jpg?v=1749635265', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir et toile', 'Plateforme', 'Slip-on', 'homme', 'Sneaker en toile et cuir', 1, 78.9474, 4, '{\n  \"nom_persona\": \"Léo Dupont\",\n   \"age_cible\": \"28-35\",\n   \"style_vie\": \"urbain-chic\",\n   \"traits_personnalite\": {\n      \"confident\": 8,\n      \"independent\": 9,\n      \"éclectique\": 7,\n      \"conscientieux\": 6,\n      \"décontracté\": 5\n   },\n   \"occasion_port\": {\n      \"jour_normal\": 6,\n      \"sortie_nuit\": 8,\n      \"week-end\": 9,\n      \"vacances\": 10\n   }\n}', -0.323129, -0.0764608, 78.9466),
(344, '10080567689549', 15, 'https://www.fillingpieces.com/products/riviera-low-navy', 'Shoes', 'Sneakers', 'Filling Pieces', 'Riviera Low Navy', 'The Riviera Low balances a relaxed spirit with sophisticated construction, defined by a unique combination of nappa, suede, and rubberized leather. Presented in a timeless Navy, this lightweight design sits on a sleek flat sole, offering a polished yet comfortable feel for everyday wear. A harmonious piece in the \'United by Rhythm\' collection, it effortlessly unites the worlds of casual ease and refined style.', 220.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133594420-1.jpg?v=1749571697', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir, suede et caoutchouc', 'Plateforme', 'Slip-on', 'homme', 'Sneaker en cuir, suede et caoutchouc', 1, 78.9474, 4, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain-chic\",\n   \"traits_personnalite\": [\n      \"independante\",\n      \"tendance\",\n      \"éclectique\",\n      \"appreciative de la qualité\",\n      \"consciente de l\'environnement\"\n   ],\n   \"occasion_port\": [\n      \"sortie avec des amis\",\n      \"rendez-vous galant\",\n      \"soirée en ville\",\n      \"week-end en famille\",\n      \"vacances\"\n   ]\n}', -0.308152, -0.293843, 78.9466),
(345, '9786269598029', 15, 'https://www.fillingpieces.com/products/mondo-suede-organic-off-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Suede Organic Off White', 'The Mondo Suede Organic Off White emphasizes sustainable and traceable materials in its construction. Featuring a premium suede leather upper with mudguards, a heel tab, and understated branding, this timeless sneaker is ideal for eco-conscious individuals seeking style, comfort, and durability in one versatile design.', 190.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133318415-1.jpg?v=1747382839', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Suede', 'Rubber sole', 'Slip-on', 'homme', 'Sneaker en suede', 1, 80.5263, 0, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": [\n      \"Consciente de l\'environnement\",\n      \"Apprécie la qualité et la durabilité\",\n      \"A un sens de l\'esthétique et de la mode\",\n      \"Est influencée par la culture streetwear\",\n      \"Apprécie la simplicité et la sobriété\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Réunions avec des amis\",\n      \"Événements de mode\",\n      \"Journées de shopping\",\n      \"Sorties en ville\"\n   ]\n}', -0.527702, -0.132175, 80.504),
(346, '9786267828557', 15, 'https://www.fillingpieces.com/products/loafer-polido-minimum-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Polido Minimum Black', 'The Loafer Polido Minimum Black offers a minimalist take on our classic loafer design. Built on a pre-fab leather and rubber sole, it’s made from premium polido leather and lined with cow leather for durability and comfort. The clean polido penny-loafer bridge makes this a versatile and elegant choice for any wardrobe. Premium quality also includes comfort. With subtle improvements to further enhance the comfort, the heel is padded with soft foam and finished in suede microfiber and the insole is also provided with cushioning foam beneath a smooth cow leather lining.', 320.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133321071-1_0a03fb62-b798-4e59-8a34-90732a310d1f.jpg?v=1748332045', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir et caoutchouc', 'Plateforme', 'Slip-on', 'homme', 'Loafer en cuir et caoutchouc', 1, 73.6842, 4, '{\n  \"nom_persona\": \"Léo Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confident\": true,\n      \"independant\": true,\n      \"élégant\": true,\n      \"prévisible\": false\n   },\n   \"occasion_port\": {\n      \"jour_nordique\": true,\n      \"soirée\": false,\n      \"week-end\": true,\n      \"réunion_professionnelle\": false\n   }\n}', -0.267372, -0.232877, 73.7183),
(347, '8916259733837', 15, 'https://www.fillingpieces.com/products/cruiser-crumbs-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Cruiser Crumbs White', 'Indulge in luxury with the Cruiser Crumbs White. Made from high-quality crumbs nappa leather and textile mesh, this shoe showcases meticulous craftsmanship. The innovative Java outsole guarantees both comfort and style, making it perfect for any occasion.', 260.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133038511_1_302473ee-755b-479d-8f42-718fcad08f62.jpg?v=1763640130', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir et toile', 'Rubber sole', 'Slip-on', 'homme', 'Sneaker en cuir et toile', 1, 76.8421, 0, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain, actif, créatif\",\n   \"traits_personnalite\": {\n      \"ouverture\": 8,\n      \"curiosité\": 9,\n      \"independance\": 7,\n      \"éclectisme\": 8,\n      \"authenticité\": 9\n   },\n   \"occasion_port\": {\n      \"journee_travail\": {\n         \"fréquence\": 5,\n         \"contexte\": \"réunion, présentation, déjeuner\"\n      },\n      \"sortie_nuit\": {\n         \"fréquence\": 3,\n         \"contexte\": \"dîner, boîte de nuit, concert\"\n      },\n      \"loisirs\": {\n         \"fréquence\": 4,\n         \"contexte\": \"shopping, café, parc\"\n      }\n   }\n}', -0.33194, -0.0575482, 76.8521),
(348, '8694816571725', 15, 'https://www.fillingpieces.com/products/riviera-low-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Riviera Low White', 'Elevate your summer style with our Riviera, a canvas sneaker that seamlessly blends relaxed comfort with timeless luxury. The shoe features a refined Nappa leather toe box and a sleek flat sole for a sophisticated touch. The Riviera is a perfect fusion of breathable fabric and premium leather, making it an ideal choice for both comfort and style.', 220.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133494935_e0a12bf0-be1a-4f56-8d34-bf9158c3f3a5.jpg?v=1747382874', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Toile et cuir', 'Plateforme', 'Slip-on', 'homme', 'Sneaker en toile et cuir', 1, 78.9474, 4, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain chic\",\n   \"traits_personnalite\": {\n      \"confident\": true,\n      \"independant\": true,\n      \"éclectique\": true,\n      \"appreciate la qualité\": true,\n      \"attaché à l\'originalité\": true\n   },\n   \"occasion_port\": {\n      \"jour de travail\": true,\n      \"sortie nocturne\": true,\n      \"week-end en ville\": true,\n      \"vacances\": true\n   }\n}', -0.323129, -0.0764608, 78.9466),
(349, '10080535839053', 15, 'https://www.fillingpieces.com/products/mondo-seamless-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Seamless White', 'An exercise in silent luxury, the Mondo Seamless is our cleanest and most refined silhouette to date. Crafted from soft European nappa leather, it utilizes special stitch-and-return seams and tonal branding to create a truly flawless, uninterrupted profile. A perfectly harmonious design, this shoe provides a quiet, steady beat for the modern wardrobe, in tune with the \'United by Rhythm\' collection.', 230.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133594932-1.jpg?v=1754582196', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Rubber sole', 'Slip-on', 'homme', 'Sneaker en cuir', 1, 78.4211, 0, '{\n  \"profil_client_idéal\": {\n      \"nom_persona\": \"Lena\",\n      \"age_cible\": {\n         \"min\": 25,\n         \"max\": 40\n      },\n      \"style_vie\": {\n         \"urban\": 0.8,\n         \"bohème\": 0.2\n      },\n      \"traits_personnalite\": {\n         \"independante\": 0.9,\n         \"confiante\": 0.8,\n         \"éclectique\": 0.7\n      },\n      \"occasion_port\": {\n         \"jour_né\": 0.4,\n         \"soirée\": 0.3,\n         \"week-end\": 0.3\n      }\n   }\n}', -0.418339, 0.0301531, 78.4128),
(350, '10080535576909', 15, 'https://www.fillingpieces.com/products/mondo-stack-suede-beige', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Stack Suede Beige', 'The classic Mondo silhouette is updated through our \'Stack\' construction, where traditional lines are redefined with layered panels. Crafted from premium suede in a versatile beige, this version replaces traditional piping with stitched overlays for added structure and depth. A contrasting heel tab provides a clean focal point, creating a look that is both architecturally interesting and effortlessly wearable.', 220.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133413424-1_ec570477-6e28-49d5-bd3f-5c6de1bddb89.jpg?v=1753109876', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Suede', 'Rubber sole', 'Slip-on', 'homme', 'Sneaker en suede', 1, 78.9474, 0, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain chic\",\n   \"traits_personnalite\": {\n      \"conformiste\": 0.2,\n      \"innovant\": 0.8,\n      \"éclectique\": 0.5,\n      \"conservateur\": 0.1,\n      \"adventurier\": 0.4\n   },\n   \"occasion_port\": {\n      \"jour de travail\": 0.6,\n      \"sortie avec amis\": 0.3,\n      \"rendez-vous romantique\": 0.1,\n      \"événement social\": 0.05,\n      \"loisirs\": 0.05\n   }\n}', -0.527702, -0.132175, 78.9466),
(351, '10080535314765', 15, 'https://www.fillingpieces.com/products/mondo-grain-off-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Grain Off White', 'The minimalist Mondo silhouette is updated with a focus on natural texture, crafted from a premium grain nappa leather. Presented in a clean, crisp \'Off White\', the leather\'s visible organic grain provides a subtle yet distinctive character to the clean design. A harmonious and foundational piece, this sneaker provides a steady rhythm for the modern wardrobe, in tune with the \'United by Rhythm\' collection.', 220.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133594826-1.jpg?v=1754582478', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Rubber sole', 'Slip-on', 'homme', 'Sneaker en cuir', 1, 78.9474, 0, '{\n  \"nom_persona\": \"Léo\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"activités\": [\"musique\", \"cinéma\", \"voyages\"],\n      \"hobbies\": [\"photographie\", \"cuisine\"],\n      \"loisirs\": [\"lecture\", \"écoute de musique\"]\n   },\n   \"traits_personnalite\": {\n      \"values\": [\"indépendance\", \"originalité\", \"qualité\"],\n      \"attitudes\": [\"éclectique\", \"curieux\", \"ouvert\"],\n      \"comportements\": [\"tendance à l\'innovation\", \"souci de la qualité\"]\n   },\n   \"occasion_port\": {\n      \"situation\": [\"sortie avec des amis\", \"rendez-vous galant\", \"soirée\"],\n      \"lieu\": [\"ville\", \"centre-ville\", \"restaurant\"],\n      \"activité\": [\"musique live\", \"dîner\", \"danser\"]\n   }\n}', -0.418339, 0.0301531, 78.9466),
(352, '10330289668429', 15, 'https://www.fillingpieces.com/products/tiebreak-core-off-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Tiebreak Core Off White', 'The Tiebreak Core Off White is an elegant addition to the luxury sneaker lineup, inspired by vintage tennis footwear. Made from premium nappa leather with refined hand-stitching and debossed silicon detailing on the heel, it offers both style and comfort. The mesh tongue enhances breathability, while the Riviera rubber cupsole and FP Gowtu knot monogram add a signature touch to this iconic design.', 240.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-Tiebreak_Core_Off_White-1_bf76c463-05d8-4539-95b9-45963d33c889.jpg?v=1764081806', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Rubber sole', 'Slip-on', 'homme', 'Sneaker en cuir', 1, 77.8947, 0, '{\n  \"nom_persona\": \"Lars\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": [\n      \"Ambitieux\",\n      \"Innovant\",\n      \"Conscient de l\'élégance\",\n      \"Appréciant la qualité\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Réunions professionnelles\",\n      \"Événements de mode\",\n      \"Journées de shopping\"\n   ]\n}', -0.418339, 0.0301531, 77.9058),
(353, '10330224230733', 15, 'https://www.fillingpieces.com/products/loafer-hazy-off-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Hazy Off White', 'The Loafer Hazy Off White offers a sophisticated, contemporary contrast on a heritage silhouette. The substantial body of the shoe is crafted from smooth black Nappa leather, setting a strong foundation for the crisp Off White Suede insert on the tongue and apron. Built on a durable Rubber sole and featuring full Leather lining for ultimate comfort, the look is completed with a classic, custom hand-shake hardware in gold.', 320.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-Loafer_Hazy_Off_White-_Plant_view.jpg?v=1768297360', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir et suede', 'Rubber sole', 'Slip-on', 'homme', 'Loafer en cuir et suede', 1, 73.6842, 0, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": {\n      \"mode\": \"chic urbain\",\n      \"influences\": [\"streetwear\", \"mode néerlandaise\"],\n      \"couleurs préférées\": [\"blanc\", \"gris\", \"beige\"]\n   },\n   \"traits_personnalite\": {\n      \"independante\": true,\n      \"éclectique\": true,\n      \"appreciative de la qualité\": true,\n      \"consciente de l\'environnement\": true\n   },\n   \"occasion_port\": {\n      \"journées de travail\": true,\n      \"sorties nocturnes\": true,\n      \"week-ends en ville\": true,\n      \"événements de mode\": true\n   }\n}', -0.404385, -0.101878, 73.7183),
(354, '10330223575373', 15, 'https://www.fillingpieces.com/products/tiebreak-core-all-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Tiebreak Core All White', 'The Tiebreak Core All White is an elegant addition to the luxury sneaker lineup, inspired by vintage tennis footwear. Made from premium nappa leather with refined hand-stitching and debossed silicon detailing on the heel, it offers both style and comfort. The mesh tongue enhances breathability, while the Riviera rubber cupsole and FP Gowtu knot monogram add a signature touch to this iconic design.', 240.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-TiebreakCoreAllWhite-1_fbdfdcd3-f24a-402c-b6dc-7056cda2759f.jpg?v=1764081548', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Rubber sole', 'Slip-on', 'homme', 'Sneaker en cuir', 1, 77.8947, 0, '{\n  \"nom_persona\": \"Léo\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"independent\",\n      \"élégant\",\n      \"conscient de la mode\",\n      \"appreciate la qualité\"\n   ],\n   \"occasion_port\": [\n      \"sortie le soir\",\n      \"rendez-vous\",\n      \"événement important\",\n      \"jour de fête\"\n   ]\n}', -0.418339, 0.0301531, 77.9058),
(355, '10330222887245', 15, 'https://www.fillingpieces.com/products/cruiser-neat-black-grey', 'Shoes', 'Sneakers', 'Filling Pieces', 'Cruiser Neat Black / Grey', 'The Cruiser Neat offers a refined, dressed-down take on our classic silhouette. Expertly crafted to blend premium quality with intentional design, this shoe maintains sophisticated without being outspoken. Presented in a versatile Black / Grey colorway, this sneaker delivers essential, high-end style that easily integrates into any modern wardrobe.', 240.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/Cruiser_Neat_Black_Grey_4.jpg?v=1764084595', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Rubber sole', 'Slip-on', 'homme', 'Sneaker en cuir', 1, 77.8947, 0, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"independante\": true,\n      \"éclectique\": true,\n      \"appreciative de la qualité\": true,\n      \"consciente de l\'environnement\": true\n   },\n   \"occasion_port\": {\n      \"journée de travail\": true,\n      \"sortie avec des amis\": true,\n      \"week-end en ville\": true,\n      \"événement culturel\": true\n   }\n}', -0.418339, 0.0301531, 77.9058),
