(357, '10080535871821', 15, 'https://www.fillingpieces.com/products/mondo-seamless-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Seamless Black', 'An exercise in silent luxury, the Mondo Seamless is our cleanest and most refined silhouette to date. Crafted from soft European nappa leather, it utilizes special stitch-and-return seams and tonal branding to create a truly flawless, uninterrupted profile. A perfectly harmonious design, this shoe provides a quiet, steady beat for the modern wardrobe, in tune with the \'United by Rhythm\' collection.', 230.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133500162-1.jpg?v=1749811472', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Rubber sole', 'Slip-on', 'homme', 'Sneaker en cuir', 1, 78.4211, 0, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"independante\",\n      \"confiante\",\n      \"éclectique\",\n      \"appreciative de la qualité\"\n   ],\n   \"occasion_port\": [\n      \"sortie avec des amis\",\n      \"rendez-vous\",\n      \"jour de travail\",\n      \"week-end en ville\"\n   ]\n}', -0.418339, 0.0301531, 78.4128),
(358, '9786268057933', 15, 'https://www.fillingpieces.com/products/loafer-reed-navy', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Reed Navy', 'Discover the Loafer Reed Navy, an innovative take on our classic loafer design. Crafted from micro-quilted diamond-shaped vegan leather and enhanced with luxury polido leather details, this stylish shoe is lined with microfiber for extra comfort and breathability. Built on our custom rubber FP Loafer sole, this versatile piece combines sustainability with sophisticated style, making it a must-have for any modern wardrobe. Our Reed Loafers come with a separate removable Gowtu Pin, included in the package. This pin is designed to be attached separately, allowing for a personalized finishing touch.', 300.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/Loafer-Reed02.jpg?v=1749652482', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir vegan', 'Rubber sole', 'Slip-on', 'homme', 'Loafer en cuir vegan', 1, 74.7368, 0, '{\n  \"nom_persona\": \"Liam\",\n   \"age_cible\": \"25-45\",\n   \"style_vie\": {\n      \"loisirs\": [\"musique\", \"cinéma\", \"voyages\"],\n      \"activités\": [\"sport\", \"lecture\", \"cuisine\"],\n      \"intérêts\": [\"mode\", \"art\", \"photographie\"]\n   },\n   \"traits_personnalite\": {\n      \"values\": [\"indépendance\", \"originalité\", \"qualité\"],\n      \"comportements\": [\"éclectique\", \"curieux\", \"ouvert\"]\n   },\n   \"occasion_port\": {\n      \"jour\": [\"rendez-vous\", \"sortie avec des amis\"],\n      \"soir\": [\"dîner\", \"sortie culturelle\"],\n      \"week-end\": [\"voyage\", \"sortie en famille\"]\n   }\n}', -0.342691, -0.0373068, 74.7631),
(359, '10330223673677', 15, 'https://www.fillingpieces.com/products/prism-peak-black-grey', 'Shoes', 'Sneakers', 'Filling Pieces', 'Prism Peak Black / Grey', 'Inspired by the dynamic fusion of running and skate culture, the Prism is a fresh take on a classic silhouette, resurrected from our archive of never-released prototypes. This sneaker showcases smart paneling with a blend of 3D mesh, supple nappa leather, and soft suede. The shoe is finished with vibrant, triple-colored rope laces and a plush footbed and lining, creating a harmonious and comfortable design.', 250.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-Prism_Peak_Black___Grey-1.jpg?v=1763389805', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir, toile et suede', 'Rubber sole', 'Slip-on', 'homme', 'Sneaker en cuir, toile et suede', 1, 77.3684, 0, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"independante\",\n      \"confiante\",\n      \"éclectique\",\n      \"appreciative de la qualité\"\n   ],\n   \"occasion_port\": [\n      \"sortie avec des amis\",\n      \"rendez-vous galant\",\n      \"événement de mode\",\n      \"journée de shopping\"\n   ]\n}', -0.363988, -0.121207, 77.3803),
(360, '10330224427341', 15, 'https://www.fillingpieces.com/products/loafer-glace-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Glace Black', 'The Loafer Glace Black is a polished, high-shine statement on the classic loafer silhouette. The entire body of the shoe is crafted from a gleaming leather blend of Polido and Nappa, delivering a mirror-like finish that demands attention. Built on a durable Rubber sole and lined fully with Leather for comfort and quality, this style is elegantly finished with sophisticated, tonal detailing at the vamp.', 320.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-Loafer_Glace_Black-1.jpg?v=1763390132', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Rubber sole', 'Slip-on', 'homme', 'Loafer en cuir', 1, 73.6842, 0, '{\n  \"nom_persona\": \"Léa Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confiance\": 8,\n      \"independance\": 9,\n      \"éclectisme\": 7,\n      \"prévisibilité\": 5\n   },\n   \"occasion_port\": {\n      \"journee_travail\": \"occasionnel\",\n      \"sortie_nuit\": \"frequent\",\n      \"weekend\": \"frequent\",\n      \"activite_physique\": \"occasionnel\",\n      \"evenement_special\": \"occasionnel\"\n   }\n}', -0.418339, 0.0301531, 73.7183),
