(363, '10330222199117', 15, 'https://www.fillingpieces.com/products/mondo-grain-grey', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Grain Grey', 'The minimalist Mondo silhouette is updated with a focus on natural texture, crafted from a premium grain nappa leather. Presented in a rich grey color, the leather\'s visible organic grain provides a subtle yet distinctive character to the clean design. A harmonious and foundational piece, this sneaker makes a good essential sneaker for any wardrobe.', 220.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-Mondo_Grain_Grey-1.jpg?v=1763388599', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Chaussure minimalist', 1, 78.9474, 2, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": [\n      \"Indépendante\",\n      \"Créative\",\n      \"Ambitieuse\",\n      \"Consciente de l\'environnement\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Réunions avec des amis\",\n      \"Événements de mode\",\n      \"Journées de shopping\"\n   ]\n}', 0.460434, -0.413131, 78.9466),
(364, '10330222526797', 15, 'https://www.fillingpieces.com/products/mondo-stack-nappa-white-grey', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Stack Nappa White / Grey', 'The Mondo Stack Nappa in White / Grey is our classic Mondo silhouette with elevated construction and detail. Crafted from layered premium nappa leather, the design has superior structure and depth. A precisely stitched panel replaces the traditional piping, emphasizing the clean lines of the shoe. The upper is finished with a contrasting heel tab for a sharp, sophisticated visual anchor.', 230.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-Mondo_Stack_Nappa_White___Grey-1.jpg?v=1763388217', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Chaussure élégante', 1, 78.4211, 2, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"independante\",\n      \"tendance\",\n      \"éclectique\",\n      \"appreciative de la qualité\"\n   ],\n   \"occasion_port\": [\n      \"sortie avec des amis\",\n      \"rendez-vous galant\",\n      \"soirée en ville\",\n      \"week-end en ville\"\n   ]\n}', 0.460434, -0.413131, 78.4128),
(365, '10330224099661', 15, 'https://www.fillingpieces.com/products/loafer-pepper-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Pepper Black', 'A classic silhouette meets vivid artistry in the Loafer Pepper Black. This design incorporates unique apparel graphics showcasing a global variety of peppers, balanced in a compelling artwork. The combination of the sleek black loafer and the intricate pepper motif creates a distinctive and confident look, perfect for those who appreciate attention-grabbing detail and refined style.', 390.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-Loafer_Pepper_Black-2.jpg?v=1763388083', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Loafer avec motif de piments', 1, 70, 2, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"ville\": \"urbaine\",\n      \"loisirs\": [\"musique\", \"art\", \"voyages\"],\n      \"mode_de_vie\": \"actif\",\n      \"priorités\": [\"qualité de vie\", \"souplesse\"]\n   },\n   \"traits_personnalite\": {\n      \"independant\": true,\n      \"éclectique\": true,\n      \"appreciate la qualité\": true,\n      \"préfère les marques de niche\": true\n   },\n   \"occasion_port\": {\n      \"journée quotidienne\": true,\n      \"sorties nocturnes\": true,\n      \"événements spéciaux\": true\n   }\n}', 0.460434, -0.413131, 70.1116),
(366, '10330224689485', 15, 'https://www.fillingpieces.com/products/loafer-broken-plate-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Broken Plate Black', 'A sophisticated tribute to the Amsterdam cityscape, the Patch Loafer Broken Plate Black is an artistic statement. The loafer\'s patch features custom artwork inspired by the known Dutch style of Delfts Blauw, with drawings of the Amsterdam canals intricately laid across a \'broken plate\' design. This shattered motif carries a universal message of good fortune, perfectly blending high-end footwear with local culture and a touch of lucky symbolism.', 390.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/SS26-LoaferBrokenPlateBlack-2_1.jpg?v=1763388111', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Loafer avec motif de canaux d\'Amsterdam', 1, 70, 2, '{\n  \"nom_persona\": \"Léo\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"loisirs\": [\"musique\", \"cinéma\", \"lecture\"],\n      \"activités\": [\"sport\", \"voyages\"],\n      \"hobbies\": [\"photographie\", \"cuisine\"]\n   },\n   \"traits_personnalite\": {\n      \"values\": [\"indépendance\", \"originalité\", \"qualité\"],\n      \"attitudes\": [\"éclectique\", \"influencé par la mode\", \"attaché à la qualité\"]\n   },\n   \"occasion_port\": {\n      \"jour_né\": \"week-end\",\n      \"soirée\": \"soirée informelle\",\n      \"activité\": [\"sortie avec des amis\", \"dîner en ville\"]\n   }\n}', 0.460434, -0.413131, 70.1116),
(367, '9786265829709', 15, 'https://www.fillingpieces.com/products/cruiser-dive-off-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Cruiser Dive Off White', 'Step into comfort with the Cruiser Dive Off White, featuring a refined blend of suede and nubuck. This stylish trainer combines depth in colors and textures, offering a full tonal look that’s perfect for everyday wear. Its modern design ensures versatility, making it a must-have for anyone seeking both style and practicality in their footwear collection.', 240.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133230229-1_a9ca5897-f1c3-493c-affa-478f5828161c.jpg?v=1763649504', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Toile', 'Caoutchouc', 'Lacets', 'homme', 'Chaussure confortable', 1, 77.8947, 2, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"indépendante\",\n      \"éclectique\",\n      \"consciente de l\'environnement\",\n      \"appreciative de la qualité\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements de mode\",\n      \"voyages\",\n      \"journées de shopping\"\n   ]\n}', 0.293006, -0.522899, 77.9058),
(368, '10330223968589', 15, 'https://www.fillingpieces.com/products/low-tide-dark-grey', 'Shoes', 'Sneakers', 'Filling Pieces', 'Low Tide Dark Grey', 'The Low Tide introduces a new, easy-going silhouette, artfully blending the sporty lines of a sprinter with the refined profile of our Prism. Crafted from a premium mix of soft suede and smooth nappa leather in a deep \'Dark Grey\', this versatile sneaker is defined by its comfortable stroble construction and a subtle, silicon-debossed Gowtu knot. The design is grounded on a custom rubber sole featuring an intricate, all-over Gowtu knot pattern for a signature finish.', 200.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133780502-1.jpg?v=1768219638', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Toile', 'Caoutchouc', 'Lacets', 'homme', 'Chaussure facile à porter', 1, 80, 2, '{\n  \"nom_persona\": \"Léo Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain, tendance, créatif\",\n   \"traits_personnalite\": [\n      \"independent\",\n      \"éclectique\",\n      \"appreciate la qualité\",\n      \"préfère les marques underground\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements culturels\",\n      \"rendez-vous amicaux\",\n      \"voyages\"\n   ]\n}', 0.293006, -0.522899, 79.995),
(369, '10330223935821', 15, 'https://www.fillingpieces.com/products/low-tide-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Low Tide White', 'The Low Tide introduces a new, easy-going silhouette, artfully blending the sporty lines of a sprinter with the refined profile of our Prism. Crafted from a premium mix of soft suede and smooth nappa leather, this versatile sneaker is defined by its comfortable stroble construction and a subtle, silicon-debossed Gowtu knot. The design is grounded on a custom rubber sole featuring an intricate, all-over Gowtu knot pattern for a signature finish.', 200.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133780304-1.jpg?v=1768235085', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Toile', 'Caoutchouc', 'Lacets', 'homme', 'Chaussure facile à porter', 1, 80, 2, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"vêtements\": \"élégant\",\n      \"chaussures\": \"comfortable\",\n      \"accessoires\": \"minimaliste\"\n   },\n   \"traits_personnalite\": {\n      \"independant\": true,\n      \"éclectique\": true,\n      \"conscientieux\": true,\n      \"authentique\": true\n   },\n   \"occasion_port\": {\n      \"jour\": \"urbain\",\n      \"soir\": \"formel\",\n      \"week-end\": \"relax\"\n   }\n}', 0.293006, -0.522899, 79.995),
(370, '10353427087693', 15, 'https://www.fillingpieces.com/products/loafer-heineken-nappa-green', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Heineken Nappa Green', 'The Loafer Heineken Nappa Green is the refined, premium version of our collaboration loafer. The upper is constructed from soft, luxurious Premium Nappa leather in a bold color combination of black and signature Heineken green. This sophisticated design is elevated by our custom FP Handshake metal bridge, which adds an element of exclusivity and high-end hardware finish.', 350.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133050339_5.jpg?v=1762513393', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Loafer avec motif de Heineken', 1, 72.1053, 2, '{\n  \"nom_persona\": \"Léo\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confident\": true,\n      \"éclectique\": true,\n      \"independent\": true,\n      \"appreciate la qualité\": true\n   },\n   \"occasion_port\": {\n      \"jour de travail\": true,\n      \"sortie avec les amis\": true,\n      \"rendez-vous romantique\": false,\n      \"événement sportif\": true\n   }\n}', 0.460434, -0.413131, 72.1679),
(371, '10353427054925', 15, 'https://www.fillingpieces.com/products/loafer-heineken-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Heineken Black', 'The Loafer Heineken Black is an outspoken statement piece from our collaboration. This classic silhouette is crafted from premium Polido leather and defined by the custom-designed FP signature chenille patch, which features the Heineken vintage logo. Grounded by a durable rubber sole, this loafer seamlessly merges high-end materials with unique, collaboration-specific artistry.', 390.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133050209_4.jpg?v=1762513342', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Loafer avec motif de Heineken', 1, 70, 2, '{\n  \"nom_persona\": \"Maxime Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"loisirs\": [\"musique\", \"cinéma\", \"voyages\"],\n      \"activités\": [\"sport\", \"lecture\", \"cuisine\"],\n      \"intérêts\": [\"mode\", \"photographie\", \"art\"]\n   },\n   \"traits_personnalite\": {\n      \"values\": [\"indépendance\", \"originalité\", \"qualité\"],\n      \"hobbies\": [\"collectionner des objets rares\", \"explorer de nouvelles cultures\"],\n      \"comportements\": [\"éclectique\", \"curieux\", \"ouvert\"]\n   },\n   \"occasion_port\": {\n      \"jour\": \"week-end\",\n      \"lieu\": \"ville\",\n      \"événement\": \"sortie avec des amis\"\n   }\n}', 0.460434, -0.413131, 70.1116),
(372, '10353427022157', 15, 'https://www.fillingpieces.com/products/riviera-heineken-antique-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Riviera Heineken Antique White', 'The Riviera Heineken Antique White offers a light, elevated take from our collaboration, using our signature Riviera silhouette as its canvas. The upper features a sophisticated blend of materials, combining durable rubberized leather with structured canvas in a soft, antique white shade. Built on a thick, custom FP sole and lined with a premium footbed, this shoe prioritizes both style and comfort. Collaboration markers include the signature FP bar-tags in a contrast color on the lateral side, and the Heineken x Filling Pieces logo lock-up debossed onto the leather heel-tab.', 220.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133049746.jpg?v=1762513262', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Loafer avec motif de Heineken', 1, 78.9474, 2, '{\n  \"nom_persona\": \"Léo Dupont\",\n   \"age_cible\": \"28-40\",\n   \"style_vie\": \"urbain élégant\",\n   \"traits_personnalite\": [\n      \"confident\",\n      \"independent\",\n      \"appreciate la qualité\",\n      \"préoccupé par l\'environnement\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements de mode\",\n      \"rendez-vous romantiques\",\n      \"voyages de style\"\n   ]\n}', 0.460434, -0.413131, 78.9466),
(373, '10353399267661', 15, 'https://www.fillingpieces.com/products/riviera-heineken-green', 'Shoes', 'Sneakers', 'Filling Pieces', 'Riviera Heineken Green', 'The Riviera Heineken Green is a unique piece from our collaboration, built upon the foundation of our classic Riviera silhouette. This style features a premium upper that combines durable rubberized leather with structured canvas in a deep green hue. The sneaker is grounded by a thick, custom FP sole and lined with a premium footbed for superior comfort. Subtle collaboration details include the signature FP bar-tags showcased in a contrast color on the lateral side, and the Heineken x Filling Pieces logo lock-up debossed onto the leather heel-tab.', 220.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/87201330498901.jpg?v=1762513016', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Loafer avec motif de Heineken', 1, 78.9474, 2, '{\n  \"nom_persona\": \"Léo Dupont\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": {\n      \"ville\": \"Marseille\",\n      \"loisirs\": [\"plage\", \"nautisme\", \"musique\"],\n      \"mode_de_vie\": \"urbain\",\n      \"activités\": [\"séjour en ville\", \"sorties nocturnes\"]\n   },\n   \"traits_personnalite\": {\n      \"ouverture\": \"ouvert\",\n      \"curiosité\": \"curieux\",\n      \"influence\": \"influenciel\",\n      \"authenticité\": \"authentique\",\n      \"éclectisme\": \"éclectique\"\n   },\n   \"occasion_port\": {\n      \"type_occasion\": \"sortie\",\n      \"lieu_occasion\": \"plage\",\n      \"activité_occasion\": \"fête\",\n      \"durée_occasion\": \"une journée\",\n      \"budget_occasion\": \"moyen\"\n   }\n}', 0.460434, -0.413131, 78.9466);
