(374, '9786267631949', 15, 'https://www.fillingpieces.com/products/loafer-bouquet-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Bouquet Black', 'The Loafer Bouquet Black is a truly unique design made from luxury polido leather. Built on a pre-fab leather and rubber sole, it features a clean leather bridge and a removable pin with a hand-made leather bouquet. Each flower is meticulously crafted from fine Italian nappa, making this loafer a standout piece that celebrates artistry and elegance. Premium quality also includes comfort. With subtle improvements to further enhance the comfort, the heel is padded with soft foam and finished in suede microfiber and the insole is also provided with cushioning foam beneath a smooth cow leather lining.', 390.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133227816-22_a8d3e0eb-d909-4e24-92b9-4d7a7c0e5775.jpg?v=1748332041', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Loafer avec bouquet de fleurs', 1, 70, 2, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"independant\": true,\n      \"éclectique\": true,\n      \"appreciate la qualité\": true,\n      \"conscient de l\'environnement\": true\n   },\n   \"occasion_port\": {\n      \"jour de travail\": true,\n      \"sorties nocturnes\": true,\n      \"week-end en ville\": true,\n      \"événements sociaux\": true\n   }\n}', 0.460434, -0.413131, 70.1116),
(375, '8970993205581', 15, 'https://www.fillingpieces.com/products/mondo-klm-blue-off-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo KLM Blue / Off-White', 'Experience the KLM X Filling Pieces Mondo: our most minimalist sneaker. Silky smooth upper made of soft blue nappa leather atop our elegant \"Fundamental Ripple\" sole. A timeless classic, updated with a KLM crown on the heel and subtle orange details.', 120.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/CopyofKLMcasual-1_3c10f7dd-741c-4981-8351-14b6270cf068.jpg?v=1773308266', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Chaussure minimalist', 1, 84.2105, 2, '{\n  \"nom_persona\": \"Léo\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": [\n      \"Ambitieux\",\n      \"Innovant\",\n      \"Conformiste\",\n      \"Passionné par la mode\",\n      \"Aptitude à l\'innovation\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Événements de mode\",\n      \"Réunions professionnelles\",\n      \"Week-ends en ville\",\n      \"Photoshoots\"\n   ]\n}', 0.460434, -0.413131, 84.1888),
(376, '8970992976205', 15, 'https://www.fillingpieces.com/products/klm-jet-runner-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'KLM Jet Runner Black', 'Experience the KLM X Filling Pieces Jet Runner: a timeless style enriched with ergonomic innovation, paying tribute to KLM\'s heritage. Made from luxurious leather and our signature Jet sole, it\'s a premium silhouette that feels light on your feet and is designed to stand the test of time.', 120.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/JetRunnerKLMblack2_bc14dfe7-c11b-48b2-a0a9-40d3dfe3b69a.jpg?v=1773308394', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Chaussure premium', 1, 84.2105, 2, '{\n  \"nom_persona\": \"Lars\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"activite\": \"urbain\",\n      \"loisirs\": [\"musique\", \"cinéma\", \"voyages\"],\n      \"mode_de_vie\": \"urbain dynamique\"\n   },\n   \"traits_personnalite\": {\n      \"independant\": true,\n      \"confiant\": true,\n      \"exigent\": true,\n      \"éclectique\": true\n   },\n   \"occasion_port\": {\n      \"journee_travail\": true,\n      \"sortie_nuit\": true,\n      \"voyage\": true,\n      \"loisirs\": true\n   }\n}', 0.460434, -0.413131, 84.1888),
(377, '8940596724045', 15, 'https://www.fillingpieces.com/products/mondo-klm-black-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo KLM Black / White', 'Experience the KLM X Filling Pieces Mondo: our most minimalist sneaker. Silky smooth upper made of soft black nappa leather atop our elegant \"Fundamental Ripple\" sole. A timeless classic, updated with a KLM crown on the heel and subtle orange details.', 120.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/87201330456874_623cc38f-17b4-425d-a579-0bebe7039372.jpg?v=1773308141', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Chaussure minimalist', 1, 84.2105, 2, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": [\n      \"Indépendante\",\n      \"Créative\",\n      \"Ambitieuse\",\n      \"Consciente de l\'environnement\",\n      \"Passionnée par la mode\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Week-ends en ville\",\n      \"Réunions avec des amis\",\n      \"Événements de mode\",\n      \"Photoshoots\"\n   ]\n}', 0.460434, -0.413131, 84.1888),
(378, '8909218742605', 15, 'https://www.fillingpieces.com/products/klm-jet-runner-blue-off-white', 'Shoes', 'Sneakers', 'Filling Pieces', 'KLM Jet Runner Blue / Off-White', 'Experience the KLM X Filling Pieces Jet Runner: a timeless style enriched with ergonomic innovation, paying tribute to KLM\'s heritage. Made from luxurious leather and our signature Jet sole, it\'s a premium silhouette that feels light on your feet and is designed to stand the test of time.', 120.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/CopyofKLMsporty-1_8861fb4f-9eab-4655-913b-36c2b87c7018.jpg?v=1773308341', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Chaussure premium', 1, 84.2105, 2, '{\n  \"nom_persona\": \"Léo Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain, tendance, actif\",\n   \"traits_personnalite\": [\n      \"independent\",\n      \"créatif\",\n      \"ambitieux\",\n      \"passionné par la mode\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements sportifs\",\n      \"voyages d\'affaires\",\n      \"rendez-vous amoureux\"\n   ]\n}', 0.460434, -0.413131, 84.1888),
(379, '9786267468109', 15, 'https://www.fillingpieces.com/products/loafer-aten-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Aten Black', 'Discover the Loafer Aten Black, a clean yet refined classic loafer built on a custom rubber FP sole unit. Featuring a perforated nappa upper with matte nappa details, this shoe combines comfort and elegance. Lined with perforated microfibers for breathability, it embodies the spirit of family and friendship through its unique design.', 220.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133226864-1_b6ffa9df-e2de-47c5-98cf-4482001f7730.jpg?v=1749652487', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Caoutchouc', 'Lacets', 'homme', 'Loafer élégant', 1, 78.9474, 2, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"loisirs\": [\"musique\", \"cinéma\", \"lecture\"],\n      \"activités\": [\"marche\", \"cyclette\", \"yoga\"],\n      \"mode de vie\": [\"urbain\", \"écologique\"]\n   },\n   \"traits_personnalite\": {\n      \"values\": [\"individualité\", \"autonomie\", \"créativité\"],\n      \"hobbies\": [\"photographie\", \"peinture\", \"écriture\"],\n      \"influences\": [\"artiste\", \"designer\", \"philosophe\"]\n   },\n   \"occasion_port\": {\n      \"journee_travail\": \"occasionnel\",\n      \"sortie_nuit\": \"fréquent\",\n      \"week-end\": \"fréquent\",\n      \"événement_spécial\": \"occasionnel\"\n   }\n}', 0.460434, -0.413131, 78.9466),
(380, '10080536887629', 15, 'https://www.fillingpieces.com/products/tiebreak-grain-rock', 'Shoes', 'Sneakers', 'Filling Pieces', 'Tiebreak Grain Rock', 'The timeless Tiebreak court shoe is updated with a distinctive, richly textured grain nubuck leather. Presented in a stone-like \'Grain Rock\' colorway, the unique texture is punctuated by a crisp. Two sets of laces offer elevated versatility, delivering a look that is both ruggedly handsome and quietly refined.', 240.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133225157-1_d301beb4-8c02-48f3-b1fb-d77419732f8a.jpg?v=1753110180', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Toile', 'Caoutchouc', 'Lacets', 'homme', 'Chaussure de tennis', 1, 77.8947, 2, '{\n  \"nom_persona\": \"Léo Dupont\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": {\n      \"activité\": \"urbaine\",\n      \"loisirs\": [\"musique\", \"cinéma\", \"voyages\"],\n      \"hobbies\": [\"photographie\", \"cuisine\"]\n   },\n   \"traits_personnalite\": {\n      \"confiance\": \"élevée\",\n      \"ouverture\": \"ouverte\",\n      \"influence\": \"moyenne\",\n      \"authenticité\": \"élevée\"\n   },\n   \"occasion_port\": {\n      \"occasion\": \"formel\",\n      \"lieu\": \"ville\",\n      \"activité\": \"sortie\"\n   }\n}', 0.293006, -0.522899, 77.9058),
(381, '10080534954317', 15, 'https://www.fillingpieces.com/products/mondo-crumbs-natural', 'Shoes', 'Sneakers', 'Filling Pieces', 'Mondo Crumbs Natural', 'The Mondo Crumbs embodies a \'less is more\' philosophy, stripping the classic silhouette back to its essential form. Its character is defined by the unique \'Crumbs Nappa\' leather, offering a subtle, fragmented texture against smooth, rubberized panels. Presented in a clean Natural colorway, this shoe is a testament to the beauty of minimalist design and premium materials', 230.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133506775-1.jpg?v=1751980871', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Chaussure minimalistique avec cuir nappa et panneaux en caoutchouc', 1, 78.4211, 1, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": {\n      \"min\": 25,\n      \"max\": 40\n   },\n   \"style_vie\": {\n      \"urban\": 0.8,\n      \"écologique\": 0.7,\n      \"sophistiqué\": 0.5\n   },\n   \"traits_personnalite\": {\n      \"influencière\": 0.6,\n      \"créative\": 0.8,\n      \"confiante\": 0.9\n   },\n   \"occasion_port\": {\n      \"journée\": {\n         \"travail\": 0.4,\n         \"loisirs\": 0.6\n      },\n      \"soirée\": {\n         \"dîner\": 0.3,\n         \"sortie\": 0.7\n      }\n   }\n}', 0.515126, 0.400522, 78.4128),
(382, '10080536494413', 15, 'https://www.fillingpieces.com/products/tiebreak-suede-navy', 'Shoes', 'Sneakers', 'Filling Pieces', 'Tiebreak Suede Navy', 'Defined by its rich texture, the Tiebreak Suede offers a sophisticated new expression of a timeless court shoe. The deep navy suede provides a refined foundation, punctuated by a crisp, bright white nappa leather heel tab. Offering elevated versatility, the design includes two distinct sets of laces in waxed cotton and nylon. Lined with supple leather, it delivers uncompromising comfort for a distinguished yet understated look.', 230.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133506805-1.jpg?v=1751981207', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Lacets', 'homme', 'Court chaussure en cuir suede avec lacets en coton et nylon', 1, 78.4211, 1, '{\n  \"nom_persona\": \"Liam\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"Urban Chic\",\n   \"traits_personnalite\": [\n      \"Ambitieux\",\n      \"Tendre\",\n      \"Conscient de l\'environnement\",\n      \"Appréciateur de la qualité\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Réunions avec des amis\",\n      \"Dates\",\n      \"Journées de shopping\"\n   ]\n}', 0.515126, 0.400522, 78.4128),
(383, '8916260389197', 15, 'https://www.fillingpieces.com/products/loafer-gradient-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Gradient Black', 'Step into sophistication with Loafer Gradient Black. Crafted from luxurious Polido leather, this loafer boasts a sleek silhouette and refined detailing. Whether for formal events or everyday wear, it promises both style and comfort.', 350.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133768722-1_bd3ffa01-cba0-4795-af59-ccca526dc7ad.jpg?v=1749652640', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Loafer en cuir polido avec silhouette élégante', 1, 72.1053, 3, '{\n  \"nom_persona\": \"Léo\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": {\n      \"confident\": true,\n      \"independent\": true,\n      \"éclectique\": true,\n      \"appreciate la qualité\": true,\n      \"préoccupé par l\'originalité\": true\n   },\n   \"occasion_port\": {\n      \"jour\": true,\n      \"soirée\": true,\n      \"week-end\": true,\n      \"sortie avec des amis\": true,\n      \"rendez-vous professionnel\": true\n   }\n}', -0.296226, 0.575709, 72.1679),
(384, '9786268844365', 15, 'https://www.fillingpieces.com/products/moc-derby-fuse-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Moc Derby Fuse Black', 'Step into the future with the Moc Derby Fuse Black, a modern and bulky take on the classic moc derby shoe. Fully re-imagined with new materials, it features a lightweight EVA sole, an upper made from polido leather, and breathable sport mesh lining. The vegan leather micro-quilted diamond collar and detailed embossed two-stripe branding add unique touches, making this shoe perfect for both style and comfort.', 300.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133228295-1_ce7c9e22-54ad-4b0f-bb73-27b4720f839c.jpg?v=1749652455', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Plateforme', 'Slip-on', 'homme', 'Moc derby en cuir polido avec semelle en EVA et mesh respirant', 1, 74.7368, 4, '{\n  \"nom_persona\": \"Léo\",\n   \"age_cible\": \"25-35\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"independent\",\n      \"tendance\",\n      \"éclectique\",\n      \"amoureux de la mode\",\n      \"passionné de la musique\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"événements de mode\",\n      \"rendez-vous amoureux\",\n      \"photoshoots\",\n      \"voyages\"\n   ]\n}', -0.473487, 0.0615615, 74.7631),
(385, '9786267992397', 15, 'https://www.fillingpieces.com/products/loafer-reed-beige-green', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Reed Beige / Green', 'The Loafer Reed Beige/Green is a detailed and innovative version of our classic loafer, crafted from micro-quilted diamond-shaped vegan leather. Enhanced with luxury polido leather details and a microfiber lining, it offers exceptional comfort and breathability. Built on our custom rubber FP Loafer sole, this shoe is perfect for the eco-conscious fashionista seeking style without compromise. Premium quality also includes comfort. With subtle improvements to further enhance the comfort, the heel is padded with soft foam and finished in suede microfiber and the insole is also provided with cushioning foam beneath a smooth cow leather lining. Our Reed Loafers come with a separate removable Gowtu Pin, included in the package. This pin is designed to be attached separately, allowing for a personalized finishing touch.', 300.00, 'AED', NULL, 0, 'out_of_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/Loafer_Reed02.jpg?v=1748332046', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Loafer en cuir micro-quilté avec détails en cuir polido', 1, 74.7368, 3, '{\n  \"nom_persona\": \"Lena\",\n   \"age_cible\": \"28-40\",\n   \"style_vie\": \"urbain\",\n   \"traits_personnalite\": [\n      \"independante\",\n      \"éclectique\",\n      \"appreciative de la qualité\"\n   ],\n   \"occasion_port\": \"journée de travail, sorties avec des amis, week-end\"\n}', -0.296226, 0.575709, 74.7631),
(386, '9786267500877', 15, 'https://www.fillingpieces.com/products/loafer-bonsai-black', 'Shoes', 'Sneakers', 'Filling Pieces', 'Loafer Bonsai Black', 'Embrace nature with the Loafer Bonsai Black, a seasonal version of our iconic Patch-Loafer line. Adorned with a chenille and embroidery patch featuring the Bonsai graphic, it reflects love and care for this special tree. Crafted from luxury polido leather with a cow-leather lining, this loafer offers exceptional quality and comfort for every occasion.', 390.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/1809/9621/files/8720133225652-2_96ce2c02-3aa5-44da-9eec-5ee8bc4fcff1.jpg?v=1748332040', '2026-03-24 16:35:34', '2026-03-24 16:35:34', '2026-04-16 20:28:53', 'Cuir', 'Gomme', 'Slip-on', 'homme', 'Loafer en cuir polido avec patch en chenille et broderie', 1, 70, 3, '{\n  \"nom_persona\": \"Léon\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"urbain, sophistiqué, éclectique\",\n   \"traits_personnalite\": [\n      \"independent\",\n      \"créatif\",\n      \"appreciate la qualité\",\n      \"préfère les marques de niche\"\n   ],\n   \"occasion_port\": [\n      \"sorties nocturnes\",\n      \"rendez-vous amicaux\",\n      \"voyages de travail\",\n      \"journées de shopping\"\n   ]\n}', -0.296226, 0.575709, 70.1116),
