(413, '10248219394229', 13, 'https://nisolo.com/products/amaya-fringe-bootie-black-suede', 'Shoes', 'Sneakers', 'Nisolo', 'Amaya Fringe Bootie Black Suede', 'The Amaya Bootie blends western-inspired design with a sleek, everyday wedge silhouette, crafted from premium waterproof suede with tonal stitching and fun fringe accent. Featuring a hidden wedge for comfortable height, a soft suede upper that molds to your foot, and a padded insole, this slip-on boot delivers all-day comfort and style.', 49.00, 'AED', NULL, 0, 'in_stock', 'https://cdn.shopify.com/s/files/1/0277/9027/files/WF-2125-Black_PAIR_FRONT.jpg?v=1759429181', '2026-03-24 16:36:16', '2026-03-24 16:36:16', '2026-04-16 20:28:53', 'Synthétique', 'Gomme', 'Slip-on', 'femme', 'Botte à talon bas confortable et style', 1, 87.9474, 3, '{\n  \"nom_persona\": \"Luna\",\n   \"age_cible\": \"25-40\",\n   \"style_vie\": \"Bohème Chic\",\n   \"traits_personnalite\": [\n      \"Indépendante\",\n      \"Créative\",\n      \"Éthique\",\n      \"Amoureuse de la nature\"\n   ],\n   \"occasion_port\": [\n      \"Sorties nocturnes\",\n      \"Week-ends en ville\",\n      \"Réunions avec des amis\",\n      \"Événements de mode\"\n   ]\n}', -0.370438, 0.247633, 87.8592),
